window.QB_TKP_B3 = [
{id:"TKP-181", q:"Seorang warga lanjut usia datang ke loket kelurahan untuk mengurus KTP. Ia sulit mendengar dan berkali-kali salah memahami penjelasan Anda. Sikap Anda ....", opts:[{t:"Berbicara dengan jelas dan perlahan sambil membantu mengisi formulirnya", s:5},{t:"Menuliskan penjelasan di kertas agar ia bisa membacanya sendiri", s:4},{t:"Meminta warga kembali lain waktu dengan membawa pendamping", s:3},{t:"Menyerahkan kepada rekan kerja agar antrean tidak tersendat", s:2},{t:"Mengeraskan suara dengan nada kesal agar ia cepat paham", s:1}], ex:"Warga lansia berhak dilayani dengan sabar dan proaktif; membantu langsung adalah bentuk pelayanan prima."},
{id:"TKP-182", q:"Antrean di loket kecamatan sangat panjang, tiba-tiba sistem aplikasi pelayanan down dan tidak bisa diakses. Tindakan Anda ....", opts:[{t:"Mengumumkan kondisi kepada warga, membagikan nomor antrean manual, dan menjelaskan estimasi waktu", s:5},{t:"Tetap melayani dengan mencatat manual tanpa memberi penjelasan kepada warga", s:4},{t:"Menutup loket sementara sampai sistem kembali normal", s:3},{t:"Menyalahkan bagian IT di depan warga yang menunggu", s:2},{t:"Membiarkan warga menunggu tanpa kejelasan", s:1}], ex:"Komunikasi terbuka dan solusi sementara menunjukkan profesionalisme saat sistem bermasalah."},
{id:"TKP-183", q:"Seorang warga pengguna kursi roda datang mengurus surat keterangan. Meja loket terlalu tinggi untuknya. Yang Anda lakukan ....", opts:[{t:"Keluar dari loket dan melayaninya di meja yang lebih rendah dengan ramah", s:5},{t:"Meminta ia menunggu hingga ada petugas lain yang bisa membantu", s:4},{t:"Melayaninya dari balik loket seperti biasa agar cepat selesai", s:3},{t:"Menyarankan ia mengutus orang lain di lain waktu", s:2},{t:"Mengabaikan kesulitannya karena semua warga diperlakukan sama", s:1}], ex:"Pelayanan inklusif berarti menyesuaikan cara melayani dengan kebutuhan difabel, bukan menyamaratakan."},
{id:"TKP-184", q:"Seorang warga marah-marah di loket karena berkasnya ditolak akibat tidak lengkap. Ia menaikkan suara di depan warga lain. Sikap Anda ....", opts:[{t:"Tetap tenang, menjelaskan syarat yang kurang dengan sopan, dan membantu membuat daftar periksa", s:5},{t:"Menjelaskan syarat dengan tegas agar ia paham aturan tidak bisa ditawar", s:4},{t:"Meminta ia tenang dulu di ruang tunggu sebelum dilayani kembali", s:3},{t:"Membalas dengan nada tinggi agar ia tidak mengulangi", s:2},{t:"Mengusirnya dari loket karena mengganggu ketertiban", s:1}], ex:"Menghadapi warga marah butuh ketenangan dan solusi, bukan emosi balasan."},
{id:"TKP-185", q:"Di tengah antrean panjang, seorang ibu hamil tua terlihat kelelahan berdiri. Tidak ada kursi kosong di ruang tunggu. Tindakan Anda ....", opts:[{t:"Mempersilakannya maju ke jalur layanan prioritas dan mencarikan tempat duduk", s:5},{t:"Meminta warga lain memberi tempat duduk kepadanya", s:4},{t:"Menyarankannya pulang dan kembali saat antrean sepi", s:3},{t:"Tetap melayaninya sesuai nomor antrean agar adil", s:2},{t:"Mengabaikannya karena semua warga antre sama lama", s:1}], ex:"Kelompok rentan seperti ibu hamil berhak atas layanan prioritas sesuai prinsip pelayanan publik."},
{id:"TKP-186", q:"Seorang pelaku UMKM ingin mengurus Nomor Induk Berusaha (NIB) tetapi kebingungan menggunakan sistem OSS. Ia sudah dua kali datang tanpa hasil. Anda ....", opts:[{t:"Memandunya langkah demi langkah hingga paham dan memberinya panduan tertulis", s:5},{t:"Membantunya mengisi langsung kali ini sambil menjelaskan", s:4},{t:"Mengarahkannya ke dinas terkait yang lebih paham OSS", s:3},{t:"Menyuruhnya belajar sendiri dari tutorial di internet", s:2},{t:"Menolak membantu karena bukan tugas kelurahan", s:1}], ex:"Pelayanan prima berarti memastikan warga benar-benar terbantu, bukan sekadar diarahkan."},
{id:"TKP-187", q:"Seorang pemuda membutuhkan surat keterangan domisili untuk melamar pekerjaan dengan tenggat hari ini juga. Berkasnya lengkap. Sikap Anda ....", opts:[{t:"Memproses segera sesuai prosedur tanpa memungut biaya tambahan apa pun", s:5},{t:"Memproses setelah antrean yang ada selesai semuanya", s:4},{t:"Memproses cepat dengan catatan ia memberi uang terima kasih", s:3},{t:"Menunda ke besok karena sudah mendekati jam pulang", s:2},{t:"Menolak karena surat lamaran bukan urusan kelurahan", s:1}], ex:"Melayani cepat sesuai prosedur tanpa pungutan adalah wujud integritas pelayanan."},
{id:"TKP-188", q:"Seorang warga datang bersama calo yang menawarkan jasa mempercepat pengurusan dengan imbalan. Warga terlihat ragu. Tindakan Anda ....", opts:[{t:"Menegaskan pelayanan gratis dan cepat, lalu melayani warga langsung tanpa perantara", s:5},{t:"Melayani warga tetapi membiarkan calo menunggu di luar", s:4},{t:"Melaporkan calo kepada atasan setelah warga pulang", s:3},{t:"Membiarkan saja karena warga yang memilih memakai calo", s:2},{t:"Ikut menawarkan jasa percepatan agar warga tidak ke calo", s:1}], ex:"Memberantas percaloan dimulai dari memastikan warga tahu layanan itu gratis dan mudah."},
{id:"TKP-189", q:"Seorang warga panik karena Kartu Keluarga miliknya hilang dan ia butuh segera untuk pendaftaran sekolah anaknya. Anda ....", opts:[{t:"Menenangkannya, menjelaskan prosedur penggantian, dan segera memproses", s:5},{t:"Menjelaskan prosedur penggantian sesuai alur yang berlaku", s:4},{t:"Memintanya membuat laporan kehilangan dulu ke polisi baru kembali", s:3},{t:"Menyuruhnya menunggu sampai arsip ditemukan", s:2},{t:"Mengatakan itu kelalaiannya sendiri sehingga harus menunggu lama", s:1}], ex:"Empati plus tindakan cepat adalah kunci melayani warga yang sedang panik."},
{id:"TKP-190", q:"Seorang warga tidak bisa membaca dan menulis datang untuk mengurus surat keterangan. Ia malu mengakuinya. Yang Anda lakukan ....", opts:[{t:"Membantu mengisi formulir dengan ramah tanpa mempermalukannya dan tanpa biaya", s:5},{t:"Membacakan dan mengisikan formulirnya dengan cepat", s:4},{t:"Memintanya membawa pendamping yang bisa menulis", s:3},{t:"Menyerahkannya kepada rekan yang lebih sabar", s:2},{t:"Menolak melayani karena formulir harus diisi sendiri", s:1}], ex:"Melindungi martabat warga sambil tetap menyelesaikan kebutuhannya adalah pelayanan beretika."},
{id:"TKP-191", q:"Di loket yang Anda jaga, seorang warga menyerobot antrean dan mengaku terburu-buru. Warga lain protes. Tindakan Anda ....", opts:[{t:"Menegur dengan sopan dan memintanya kembali ke antrean sesuai nomor", s:5},{t:"Melayaninya cepat agar tidak ribut, lalu kembali ke antrean normal", s:4},{t:"Membiarkan warga lain yang menegurnya", s:3},{t:"Memarahinya di depan umum agar jera", s:2},{t:"Mendahulukannya karena ia terlihat penting", s:1}], ex:"Menegakkan ketertiban antrean secara sopan menjaga keadilan bagi semua warga."},
{id:"TKP-192", q:"Akun media sosial resmi kelurahan menerima komplain warga tentang pelayanan yang lambat kemarin. Sebagai admin, Anda ....", opts:[{t:"Menanggapi cepat dengan empati, meminta data, dan menindaklanjuti ke bidang terkait", s:5},{t:"Membalas dengan penjelasan prosedur pelayanan yang berlaku", s:4},{t:"Meneruskan keluhan ke atasan dan menunggu arahan", s:3},{t:"Menghapus komentar agar tidak dibaca warga lain", s:2},{t:"Mengabaikannya karena komplain medsos bukan jalur resmi", s:1}], ex:"Komplain di ruang publik harus ditangani cepat dan transparan sebagai akuntabilitas."},
{id:"TKP-193", q:"Listrik padam saat jam pelayanan. Komputer mati dan warga sudah banyak antre. Keputusan Anda ....", opts:[{t:"Melayani yang bisa dilayani manual, mencatat sisanya, dan meminta kontak warga untuk dihubungi", s:5},{t:"Tetap melayani dengan pencatatan manual seadanya", s:4},{t:"Menutup pelayanan sampai listrik menyala kembali", s:3},{t:"Menyalahkan PLN di depan warga yang kecewa", s:2},{t:"Pulang lebih awal karena tidak bisa bekerja", s:1}], ex:"Kondisi darurat menuntut kreativitas agar pelayanan tetap berjalan semaksimal mungkin."},
{id:"TKP-194", q:"Seorang warga menyerahkan fotokopi KTP yang buram dan hampir tidak terbaca untuk pengurusan surat. Ia tidak membawa aslinya. Anda ....", opts:[{t:"Memintanya menunjukkan aslinya atau memfotokopi ulang, dan membantu memfotokopi di kantor bila tersedia", s:5},{t:"Menerima seadanya dan mencoba memproses", s:4},{t:"Menolak dan memintanya kembali lain waktu dengan berkas jelas", s:3},{t:"Memproses dengan data seadanya agar cepat", s:2},{t:"Menuduhnya memalsukan dokumen", s:1}], ex:"Membantu warga memenuhi syarat lebih baik daripada sekadar menolak atau meloloskan berkas cacat."},
{id:"TKP-195", q:"Seorang remaja datang pertama kali mengurus KTP-el. Ia tampak canggung dan takut salah. Sikap Anda ....", opts:[{t:"Menyambut ramah, menjelaskan alur dengan sederhana, dan memandunya sampai selesai", s:5},{t:"Menjelaskan alur pengurusan sesuai prosedur", s:4},{t:"Memberinya brosur dan memintanya membaca sendiri", s:3},{t:"Melayaninya seperti warga lain tanpa perlakuan khusus", s:2},{t:"Menyuruhnya bertanya kepada warga lain yang antre", s:1}], ex:"Keramahan pada pengalaman pertama warga membangun kepercayaan terhadap pelayanan publik."},
{id:"TKP-196", q:"Seorang warga menyelipkan uang dalam berkasnya sambil berbisik agar pengurusannya dipercepat. Di sekitar ada warga lain antre. Anda ....", opts:[{t:"Menolak tegas dengan sopan, mengembalikan uangnya, dan melayaninya sesuai antrean", s:5},{t:"Menolak uangnya tetapi tetap mendahulukannya karena kasihan", s:4},{t:"Mengambil uangnya lalu melayani seperti biasa", s:3},{t:"Menerima dan mempercepat pengurusannya", s:2},{t:"Melaporkannya ke polisi karena percobaan suap", s:1}], ex:"Menolak gratifikasi secara tegas namun sopan menjaga integritas tanpa mempermalukan warga."},
{id:"TKP-197", q:"Seorang warga ingin mengurus surat keterangan usaha tetapi belum memiliki surat pengantar RT. Ia mengaku RT-nya sulit ditemui. Anda ....", opts:[{t:"Membantu menghubungi RT setempat dan menjelaskan alternatif pengantar yang sah", s:5},{t:"Menjelaskan ia harus melengkapi pengantar RT dulu", s:4},{t:"Menerbitkan surat tanpa pengantar demi membantu", s:3},{t:"Menolak dan memintanya kembali setelah lengkap", s:2},{t:"Menyuruhnya mencari RT lain yang mau tanda tangan", s:1}], ex:"Membantu menyelesaikan kendala administrasi lebih baik daripada kaku menolak atau melanggar prosedur."},
{id:"TKP-198", q:"Seorang warga berbeda keyakinan dengan mayoritas membutuhkan surat keterangan untuk keperluan ibadahnya. Beberapa warga berbisik keberatan. Anda ....", opts:[{t:"Melayaninya sama seperti warga lain karena itu haknya yang dijamin", s:5},{t:"Melayaninya dengan cepat agar tidak menjadi perhatian", s:4},{t:"Memintanya mengurus di tempat ibadahnya saja", s:3},{t:"Menunda pelayanannya sampai situasi kondusif", s:2},{t:"Menolak karena khawatir protes warga lain", s:1}], ex:"Pelayanan publik tidak boleh diskriminatif; hak setiap warga dijamin konstitusi."},
{id:"TKP-199", q:"Seorang kakek datang sendirian mengurus surat ahli waris. Ia bingung dengan istilah-istilah formulir dan terlihat lelah. Tindakan Anda ....", opts:[{t:"Mendampinginya dengan sabar dari awal sampai berkas selesai diproses", s:5},{t:"Menjelaskan istilah-istilah sulit dengan bahasa sederhana", s:4},{t:"Memintanya pulang dan kembali bersama anaknya", s:3},{t:"Memberinya formulir untuk diisi di rumah", s:2},{t:"Melayaninya seadanya karena antrean masih panjang", s:1}], ex:"Warga rentan berhak atas pendampingan penuh, bukan sekadar penjelasan."},
{id:"TKP-200", q:"Rekan satu loket izin mendadak, sehingga Anda harus menangani dua loket sendirian saat antrean membludak. Sikap Anda ....", opts:[{t:"Tetap membuka kedua layanan dengan mengatur antrean sebaik mungkin dan meminta bantuan bila perlu", s:5},{t:"Melayani satu loket saja agar kualitas terjaga", s:4},{t:"Menutup satu loket dan memasang pengumuman", s:3},{t:"Mengeluh kepada warga tentang rekan yang izin", s:2},{t:"Ikut izin karena beban terlalu berat", s:1}], ex:"Tanggung jawab pelayanan tidak boleh berhenti karena kendala personel; cari solusi terbaik."},
{id:"TKP-201", q:"Seorang warga mengeluh kepada Anda bahwa petugas loket sebelah (rekan Anda) bersikap judes kepadanya kemarin. Anda ....", opts:[{t:"Menerima keluhan dengan empati, meminta maaf atas nama layanan, dan menyampaikannya secara bijak kepada rekan", s:5},{t:"Meminta maaf dan berjanji akan menyampaikan kepada atasan", s:4},{t:"Membela rekan dengan mengatakan mungkin ia sedang lelah", s:3},{t:"Menyuruh warga melapor resmi bila merasa dirugikan", s:2},{t:"Mengabaikan karena bukan Anda yang dikeluhkan", s:1}], ex:"Keluhan warga adalah masukan berharga; ditangani empatik sekaligus menjaga kekompakan tim."},
{id:"TKP-202", q:"Seorang pedagang kaki lima ingin mengurus surat keterangan usaha untuk mengakses bantuan modal. Ia belum punya tempat usaha tetap. Anda ....", opts:[{t:"Melakukan verifikasi sederhana dan memproses suratnya sesuai ketentuan", s:5},{t:"Memproses dengan catatan keterangan lokasi berjualan", s:4},{t:"Menolak karena tidak ada tempat usaha tetap", s:3},{t:"Mengarahkannya mengurus izin yang lebih tinggi dulu", s:2},{t:"Memintanya kembali setelah punya kios", s:1}], ex:"Pelayanan harus adaptif terhadap realitas warga kecil, bukan kaku pada formalitas."},
{id:"TKP-203", q:"Seseorang meminta salinan data kependudukan tetangganya dengan alasan ingin membantu. Ia bukan keluarga dan tanpa surat kuasa. Anda ....", opts:[{t:"Menolak dengan sopan sambil menjelaskan perlindungan data pribadi", s:5},{t:"Memberi sebagian data yang dianggap tidak sensitif", s:4},{t:"Memintanya kembali dengan surat kuasa dari yang bersangkutan", s:3},{t:"Memberikan karena alasannya terdengar baik", s:2},{t:"Mengusirnya karena dicurigai berniat jahat", s:1}], ex:"Data pribadi warga dilindungi undang-undang; niat baik bukan alasan melanggarnya."},
{id:"TKP-204", q:"Terjadi bentrok antara warga pendaftar online dan offline yang sama-sama merasa didahulukan. Suasana memanas. Anda ....", opts:[{t:"Membuat dan mengumumkan alur antrean yang jelas dan adil untuk kedua jalur", s:5},{t:"Mendahulukan yang datang lebih dulu tanpa memandang jalur", s:4},{t:"Menutup pendaftaran online hari itu", s:3},{t:"Membiarkan mereka beradu argumen sampai lelah", s:2},{t:"Memihak pendaftar offline karena sudah antre fisik", s:1}], ex:"Konflik antrean diselesaikan dengan sistem yang transparan dan adil bagi semua."},
{id:"TKP-205", q:"Seorang warga tunanetra perlu menandatangani berkas pengurusan. Ia khawatir salah tanda tangan. Yang Anda lakukan ....", opts:[{t:"Membacakan isi dokumen dengan jelas lalu memandunya menandatangani di tempat yang tepat", s:5},{t:"Mengarahkannya membuat cap jempol sebagai pengganti", s:4},{t:"Memintanya membawa pendamping untuk menandatangani", s:3},{t:"Menandatangani atas namanya dengan izinnya", s:2},{t:"Menolak memproses karena tidak bisa tanda tangan", s:1}], ex:"Memastikan warga difabel memahami dan menandatangani sendiri menjunjung martabatnya."},
{id:"TKP-206", q:"Hujan deras, banyak warga kehujanan saat antre di luar karena ruang tunggu penuh. Tindakan Anda ....", opts:[{t:"Mempersilakan mereka berteduh di dalam, mengatur ulang antrean, dan mempercepat alur", s:5},{t:"Membuka pintu ruangan agar mereka bisa berteduh", s:4},{t:"Membagikan nomor antrean agar mereka bisa menunggu di tempat teduh", s:3},{t:"Membiarkan karena ruang memang terbatas", s:2},{t:"Meminta mereka pulang dan kembali saat hujan reda", s:1}], ex:"Empati dalam kondisi darurat kecil menunjukkan pelayanan yang manusiawi."},
{id:"TKP-207", q:"Seorang warga protes karena diminta membayar biaya yang menurutnya seharusnya gratis. Ia menunjuk papan informasi yang sudah kusam. Anda ....", opts:[{t:"Menjelaskan rincian biaya resmi, menunjukkan dasar aturannya, dan memperbaiki papan informasi", s:5},{t:"Menjelaskan bahwa biaya tersebut memang resmi", s:4},{t:"Membebaskannya dari biaya agar tidak ribut", s:3},{t:"Menyuruhnya membaca sendiri papan informasi", s:2},{t:"Mengatakan itu sudah ketentuan dan tidak bisa diganggu gugat", s:1}], ex:"Transparansi biaya plus perbaikan informasi mencegah kesalahpahaman berulang."},
{id:"TKP-208", q:"Seorang warga yang berduka datang mengurus surat keterangan kematian orang tuanya untuk keperluan ahli waris. Ia masih terpukul. Anda ....", opts:[{t:"Melayaninya dengan empati, memproses cepat, dan menyederhanakan langkah yang bisa disederhanakan", s:5},{t:"Memproses sesuai prosedur dengan sikap simpatik", s:4},{t:"Memintanya melengkapi semua berkas dulu seperti biasa", s:3},{t:"Menyerahkannya kepada rekan karena tidak tega", s:2},{t:"Melayaninya seadanya agar cepat selesai", s:1}], ex:"Warga berduka butuh kemudahan dan empati, bukan birokrasi kaku."},
{id:"TKP-209", q:"Seorang ibu membawa balita yang rewel sambil mengurus surat. Ia kewalahan menenangkan anaknya. Tindakan Anda ....", opts:[{t:"Mendahulukan pelayanannya atau menyediakan ruang tunggu yang nyaman untuknya", s:5},{t:"Mempercepat proses pengurusannya", s:4},{t:"Memintanya menitipkan anaknya dulu", s:3},{t:"Menegurnya karena anaknya mengganggu", s:2},{t:"Membiarkannya antre seperti biasa", s:1}], ex:"Fleksibilitas untuk ibu dengan anak kecil adalah wujud pelayanan ramah keluarga."},
{id:"TKP-210", q:"Lima menit sebelum jam istirahat, seorang warga datang dari jauh untuk pengurusan sederhana. Rekan Anda sudah menutup loketnya. Anda ....", opts:[{t:"Tetap melayaninya sampai selesai karena ia sudah datang", s:5},{t:"Melayaninya cepat sebelum istirahat", s:4},{t:"Memintanya menunggu sampai jam istirahat selesai", s:3},{t:"Mengikuti rekan menutup loket tepat waktu", s:2},{t:"Menyuruhnya kembali besok", s:1}], ex:"Pelayanan prima kadang berarti sedikit melampaui jam demi warga yang sudah datang jauh."},
{id:"TKP-211", q:"Seorang warga membawa 25 berkas untuk legalisir sekaligus. Antrean di belakangnya panjang. Tindakan Anda ....", opts:[{t:"Melayaninya bertahap dengan memberi estimasi waktu dan tetap menjaga antrean berjalan", s:5},{t:"Melayaninya semua sekaligus meski antrean menunggu lama", s:4},{t:"Memintanya kembali besok agar antrean tidak tersendat", s:3},{t:"Menolak sebagian berkasnya", s:2},{t:"Menyuruhnya mencari jasa legalisir swasta", s:1}], ex:"Menyeimbangkan kebutuhan satu warga dengan kepentingan antrean adalah manajemen pelayanan yang baik."},
{id:"TKP-212", q:"Nama warga di Kartu Keluarga tertulis salah satu huruf, sehingga ditolak saat pendaftaran sekolah. Ia butuh perbaikan segera. Anda ....", opts:[{t:"Membantu koreksi data sesuai prosedur dan memprioritaskan karena kebutuhan mendesak", s:5},{t:"Memproses koreksi sesuai alur yang berlaku", s:4},{t:"Menyuruhnya mengurus ke dukcapil kabupaten langsung", s:3},{t:"Menunda karena koreksi data butuh waktu lama", s:2},{t:"Menyalahkannya karena tidak teliti sejak awal", s:1}], ex:"Kesalahan administrasi harus diperbaiki dengan cepat terutama bila berdampak pada hak warga."},
{id:"TKP-213", q:"Seorang warga lupa membawa KTP asli, hanya ada fotokopinya, untuk pengurusan yang membutuhkan verifikasi identitas. Anda ....", opts:[{t:"Menjelaskan syaratnya dan menawarkan alternatif identitas resmi lain yang ia bawa", s:5},{t:"Menerima fotokopi karena wajahnya cocok", s:4},{t:"Menolak dan memintanya kembali dengan KTP asli", s:3},{t:"Memproses tanpa verifikasi agar cepat", s:2},{t:"Menuduhnya bukan pemilik identitas", s:1}], ex:"Menawarkan solusi alternatif lebih membantu daripada kaku menolak atau longgar melanggar aturan."},
{id:"TKP-214", q:"Sebuah keluarga pindah domisili antar kabupaten dan butuh Surat Keterangan Pindah Warga Negara Indonesia. Mereka bingung alurnya. Anda ....", opts:[{t:"Menjelaskan alur lengkap antar daerah dan membantu menyiapkan berkas tahap pertama", s:5},{t:"Memberi daftar syarat yang harus dilengkapi", s:4},{t:"Mengarahkan langsung ke dukcapil kabupaten", s:3},{t:"Menyuruh mereka bertanya ke daerah tujuan", s:2},{t:"Menolak karena pindah antar kabupaten bukan wewenang kelurahan", s:1}], ex:"Pelayanan yang tuntas berarti memandu warga memahami alur, bukan melempar ke instansi lain."},
{id:"TKP-215", q:"Seorang lansia renta antre sambil berdiri karena kursi prioritas penuh. Ia tampak gemetar. Yang Anda lakukan ....", opts:[{t:"Segera mencarikan kursi dan mendahulukan pelayanannya", s:5},{t:"Meminta warga muda mengalah memberi tempat duduk", s:4},{t:"Menyarankannya duduk di lantai sementara", s:3},{t:"Membiarkan karena kursi memang terbatas", s:2},{t:"Menganggapnya risiko sendiri datang saat ramai", s:1}], ex:"Keselamatan dan kenyamanan lansia adalah prioritas yang tidak bisa ditawar."},
{id:"TKP-216", q:"Mesin nomor antrean digital error dan menampilkan nomor acak. Warga mulai ribut. Tindakan Anda ....", opts:[{t:"Beralih ke nomor manual sementara, mengumumkan dengan jelas, dan melaporkan kerusakan", s:5},{t:"Memakai nomor manual tanpa penjelasan", s:4},{t:"Menutup pendaftaran sampai mesin diperbaiki", s:3},{t:"Menyalahkan vendor mesin di depan warga", s:2},{t:"Membiarkan warga berebut nomor", s:1}], ex:"Gangguan teknis diatasi dengan sistem cadangan dan komunikasi yang menenangkan."},
{id:"TKP-217", q:"Seorang warga menelepon menanyakan status berkasnya yang sudah seminggu diajukan. Ia khawatir berkasnya hilang. Anda ....", opts:[{t:"Mengecek statusnya segera dan menginformasikan dengan jelas plus estimasi selesai", s:5},{t:"Mengecek dan menyampaikan statusnya", s:4},{t:"Memintanya datang langsung untuk mengecek", s:3},{t:"Menjawab seingatnya tanpa mengecek", s:2},{t:"Mengatakan tidak tahu dan menutup telepon", s:1}], ex:"Kepastian informasi yang cepat menenangkan warga dan menunjukkan akuntabilitas."},
{id:"TKP-218", q:"Seorang warga kurang mampu butuh surat keterangan tidak mampu untuk beasiswa anaknya dengan tenggat dua hari. Berkas pendukungnya kurang satu. Anda ....", opts:[{t:"Membantu melengkapi kekurangan dengan verifikasi cepat dan memproses segera", s:5},{t:"Memproses setelah berkas lengkap", s:4},{t:"Menolak karena berkas tidak lengkap", s:3},{t:"Mengarahkan ke dinsos tanpa membantu", s:2},{t:"Memungut biaya percepatan", s:1}], ex:"Kebutuhan mendesak warga kurang mampu layak mendapat percepatan yang tetap prosedural."},
{id:"TKP-219", q:"Seorang warga menyerahkan dokumen pendukung berbahasa asing untuk pengurusan surat. Anda tidak memahaminya. Sikap Anda ....", opts:[{t:"Menjelaskan ia perlu terjemahan tersumpah dan memberi daftar penerjemah resmi", s:5},{t:"Menerima dokumen apa adanya", s:4},{t:"Menolak karena tidak bisa memverifikasi", s:3},{t:"Memproses dengan asumsi isinya benar", s:2},{t:"Menuduh dokumennya palsu", s:1}], ex:"Memberi jalan keluar yang sah lebih baik daripada menerima buta atau menolak mentah."},
{id:"TKP-220", q:"Loket hampir tutup, masih ada tiga warga antre dengan pengurusan sederhana. Rekan Anda sudah berkemas. Anda ....", opts:[{t:"Menyelesaikan ketiganya karena pengurusannya sederhana dan mereka sudah antre", s:5},{t:"Melayani satu orang tercepat saja", s:4},{t:"Memberi nomor antrean untuk besok pagi", s:3},{t:"Menutup loket tepat waktu seperti rekan", s:2},{t:"Menyuruh mereka datang lebih pagi besok", s:1}], ex:"Menyelesaikan warga yang sudah antre adalah tanggung jawab hingga tuntas."},
{id:"TKP-221", q:"Seorang warga tunarungu datang mengurus surat. Ia berkomunikasi dengan isyarat yang tidak Anda pahami sepenuhnya. Tindakan Anda ....", opts:[{t:"Berkomunikasi lewat tulisan dengan sabar sampai maksudnya jelas, lalu melayani", s:5},{t:"Mencoba isyarat sederhana yang Anda bisa", s:4},{t:"Memintanya membawa penerjemah isyarat", s:3},{t:"Menyerahkannya kepada rekan lain", s:2},{t:"Mengabaikannya karena sulit berkomunikasi", s:1}], ex:"Hambatan komunikasi diatasi dengan kesabaran dan cara alternatif, bukan penolakan."},
{id:"TKP-222", q:"Warga ingin mengurus surat izin keramaian untuk hajatan. Ia tidak tahu harus koordinasi ke mana saja. Anda ....", opts:[{t:"Menjelaskan alur termasuk koordinasi kepolisian dan membantu menyiapkan suratnya", s:5},{t:"Menerbitkan surat dari kelurahan saja", s:4},{t:"Mengarahkan langsung ke polsek", s:3},{t:"Menolak karena izin keramaian bukan wewenang kelurahan", s:2},{t:"Menyuruhnya membatalkan acara", s:1}], ex:"Pelayanan tuntas mencakup informasi koordinasi lintas instansi yang dibutuhkan warga."},
{id:"TKP-223", q:"Seorang warga kecewa karena pengurusannya molor dua hari dari janji. Ia menyampaikan dengan nada kecewa tetapi sopan. Anda ....", opts:[{t:"Meminta maaf, menjelaskan penyebabnya, dan mempercepat penyelesaiannya hari itu juga", s:5},{t:"Meminta maaf dan berjanji segera diselesaikan", s:4},{t:"Menjelaskan bahwa keterlambatan hal biasa", s:3},{t:"Menyalahkan bagian lain yang menghambat", s:2},{t:"Mengatakan ia harus bersabar", s:1}], ex:"Permintaan maaf tulus plus aksi percepatan memulihkan kepercayaan warga."},
{id:"TKP-224", q:"Seorang anak yatim piatu yang diasuh neneknya butuh surat keterangan untuk pengurusan bantuan. Neneknya bingung administrasi. Anda ....", opts:[{t:"Membantu mengurus hingga tuntas dan mengoordinasikan dengan dinsos bila perlu", s:5},{t:"Membantu mengisi dan memproses suratnya", s:4},{t:"Memberi daftar syarat untuk dilengkapi", s:3},{t:"Mengarahkan ke dinsos langsung", s:2},{t:"Menolak karena bukan program kelurahan", s:1}], ex:"Anak rentan berhak atas bantuan ekstra hingga kebutuhannya benar-benar terpenuhi."},
{id:"TKP-225", q:"Seorang warga meminta surat rekomendasi kelurahan untuk pengajuan kredit bank. Isi rekomendasinya di luar kewenangan Anda. Sikap Anda ....", opts:[{t:"Menjelaskan batas kewenangan dan menerbitkan surat sesuai format yang dibenarkan", s:5},{t:"Menerbitkan sesuai permintaan agar ia terbantu", s:4},{t:"Menolak mentah-mentah", s:3},{t:"Mengarahkan ke notaris", s:2},{t:"Menerbitkan dengan imbalan", s:1}], ex:"Membantu warga tidak boleh melampaui kewenangan; kejujuran batas wewenang adalah integritas."},
{id:"TKP-226", q:"Banjir merendam kantor kelurahan setinggi lutut. Warga tetap berdatangan butuh surat mendesak. Keputusan Anda ....", opts:[{t:"Membuka posko layanan darurat di tempat kering dan memprioritaskan yang mendesak", s:5},{t:"Melayani seadanya dari teras kantor", s:4},{t:"Menutup total sampai banjir surut", s:3},{t:"Menyuruh warga ke kelurahan tetangga", s:2},{t:"Pulang karena kantor tidak layak", s:1}], ex:"Bencana bukan alasan berhenti melayani; layanan darurat menunjukkan dedikasi."},
{id:"TKP-227", q:"Seseorang datang dengan surat kuasa untuk mengurus dokumen ibunya yang sakit. Surat kuasa bermaterai tetapi tanpa cap RT. Anda ....", opts:[{t:"Memverifikasi keabsahan kuasa lewat kontak yang tertera, lalu memproses bila sah", s:5},{t:"Menerima kuasa apa adanya demi kemanusiaan", s:4},{t:"Menolak karena tidak ada cap RT", s:3},{t:"Memproses tanpa verifikasi", s:2},{t:"Menuduhnya memalsukan kuasa", s:1}], ex:"Verifikasi proporsional menyeimbangkan kemudahan dan keamanan administrasi."},
{id:"TKP-228", q:"Seorang warga meminta duplikat surat keterangan yang pernah diterbitkan setahun lalu karena aslinya rusak. Arsipnya sulit ditemukan. Anda ....", opts:[{t:"Mencari di arsip dengan sungguh-sungguh dan menerbitkan duplikatnya", s:5},{t:"Mencoba mencari sebisanya", s:4},{t:"Memintanya mengurus surat baru saja", s:3},{t:"Menolak karena arsip tidak ditemukan", s:2},{t:"Menyuruhnya melupakan surat lama itu", s:1}], ex:"Kesungguhan mencari arsip menunjukkan tanggung jawab atas dokumen yang pernah diterbitkan."},
{id:"TKP-229", q:"Melalui pesan WhatsApp resmi, warga bertanya panjang lebar tentang syarat mengurus KK baru. Pesan masuk di luar jam kerja. Anda ....", opts:[{t:"Menjawab dengan ramah dan lengkap saat memungkinkan, atau pagi harinya", s:5},{t:"Menjawab singkat dengan daftar syarat", s:4},{t:"Membalas dengan template otomatis saja", s:3},{t:"Mengabaikan karena di luar jam kerja", s:2},{t:"Memblokir karena mengganggu waktu pribadi", s:1}], ex:"Responsif di kanal resmi, dengan tetap menjaga batas wajar, adalah pelayanan modern."},
{id:"TKP-230", q:"Kotak survei kepuasan masyarakat (SKM) sepi pengisi. Atasan meminta tingkat partisipasi naik. Tindakan Anda ....", opts:[{t:"Mengajak warga mengisi dengan jujur dan menindaklanjuti hasilnya untuk perbaikan", s:5},{t:"Meminta warga mengisi setiap selesai dilayani", s:4},{t:"Mengisi sendiri sebagian agar target tercapai", s:3},{t:"Memaksa warga mengisi sebelum dilayani", s:2},{t:"Mengabaikan karena survei tidak penting", s:1}], ex:"Survei bermakna bila jujur dan ditindaklanjuti, bukan sekadar angka."},
{id:"TKP-231", q:"Seorang warga menyelipkan bingkisan parsel sambil berkata terima kasih atas bantuan kemarin. Nilainya cukup besar. Sikap Anda ....", opts:[{t:"Menolak dengan halus sambil menjelaskan aturan gratifikasi", s:5},{t:"Menerima karena sudah terjadi dan nilainya wajar", s:4},{t:"Menerima lalu membagikan ke rekan-rekan", s:3},{t:"Menolak tetapi tersinggung", s:2},{t:"Meminta parsel lebih besar lain waktu", s:1}], ex:"Menolak gratifikasi secara halus menjaga integritas tanpa merusak hubungan baik."},
{id:"TKP-232", q:"Rekan kerja mengajak Anda ikut menggelembungkan anggaran kegiatan agar ada sisa untuk dibagi. Ia bilang sudah biasa. Anda ....", opts:[{t:"Menolak tegas dan mengingatkannya tentang risikonya", s:5},{t:"Menolak tetapi tidak berani menegur", s:4},{t:"Ikut diam saja tidak terlibat", s:3},{t:"Melaporkannya diam-diam ke atasan", s:2},{t:"Ikut serta karena sudah biasa", s:1}], ex:"Menolak dan mengingatkan adalah keberanian moral menghadapi ajakan korupsi."},
{id:"TKP-233", q:"Atasan meminta Anda mendahulukan pengurusan milik kerabatnya yang baru datang, melewati antrean warga. Anda ....", opts:[{t:"Menolak dengan halus dan tetap melayani sesuai antrean", s:5},{t:"Mendahulukan tetapi merahasiakan", s:4},{t:"Meminta atasan memberi perintah tertulis dulu", s:3},{t:"Mendahulukan karena perintah atasan", s:2},{t:"Mendahulukan sambil meminta imbalan", s:1}], ex:"Integritas berarti berani menolak perintah yang melanggar keadilan, dengan cara santun."},
{id:"TKP-234", q:"Saat menutup kas layanan, Anda menemukan kelebihan uang yang tidak jelas asalnya. Tindakan Anda ....", opts:[{t:"Melaporkan dan menyetorkannya sesuai prosedur", s:5},{t:"Menyimpannya dulu sambil mencari pemiliknya", s:4},{t:"Membaginya dengan rekan shift", s:3},{t:"Mengambilnya karena tidak ada yang tahu", s:2},{t:"Membiarkannya di laci kas", s:1}], ex:"Kelebihan kas sekecil apa pun harus dilaporkan; kejujuran tidak mengenal nominal."},
{id:"TKP-235", q:"Seorang warga meminta Anda memalsukan tanda tangan lurah yang sedang dinas luar agar suratnya cepat jadi. Anda ....", opts:[{t:"Menolak tegas dan menjelaskan risikonya, lalu menawarkan solusi resmi", s:5},{t:"Menolak tetapi tidak menjelaskan", s:4},{t:"Menunda sampai lurah kembali", s:3},{t:"Memalsukan karena kasihan", s:2},{t:"Memalsukan dengan imbalan", s:1}], ex:"Pemalsuan dokumen adalah pelanggaran hukum; penolakan tegas melindungi semua pihak."},
{id:"TKP-236", q:"Laporan bulanan harus dikumpulkan besok pagi, tetapi data dari dua seksi belum masuk. Anda penanggung jawabnya. Sikap Anda ....", opts:[{t:"Menghubungi seksi terkait segera, lembur bila perlu, agar laporan tepat waktu", s:5},{t:"Membuat laporan dengan data yang ada dan memberi catatan", s:4},{t:"Meminta perpanjangan tenggat ke atasan", s:3},{t:"Menyalahkan seksi yang terlambat", s:2},{t:"Mengarang data agar terlihat lengkap", s:1}], ex:"Tanggung jawab berarti proaktif menyelesaikan, bukan mencari alasan atau memalsukan."},
{id:"TKP-237", q:"Anda sadar salah menginput nomor NIK warga sehingga suratnya salah cetak. Warga sudah pulang. Tindakan Anda ....", opts:[{t:"Mengakui, memperbaiki, mencetak ulang, dan menghubungi warga untuk mengambil yang benar", s:5},{t:"Memperbaiki dan menunggu warga komplain", s:4},{t:"Menyalahkan sistem yang error", s:3},{t:"Membiarkan karena warga tidak akan sadar", s:2},{t:"Menyembunyikan kesalahan", s:1}], ex:"Mengakui dan memperbaiki kesalahan sendiri adalah integritas yang sesungguhnya."},
{id:"TKP-238", q:"Pihak luar menelepon mengaku wartawan dan meminta data pribadi warga tertentu untuk bahan berita. Anda ....", opts:[{t:"Menolak dan mengarahkannya ke pejabat yang berwenang memberi keterangan", s:5},{t:"Memberi data umum yang tidak sensitif", s:4},{t:"Memintanya datang dengan surat resmi dulu", s:3},{t:"Memberikan karena ia wartawan", s:2},{t:"Memberikan dengan imbalan", s:1}], ex:"Data warga bukan konsumsi publik; hanya pejabat berwenang yang boleh memberi keterangan resmi."},
{id:"TKP-239", q:"Rekan meminta Anda mencatatkan kehadirannya padahal ia belum datang (titip absen). Anda ....", opts:[{t:"Menolak dengan tegas karena itu kecurangan", s:5},{t:"Menolak tetapi merasa tidak enak", s:4},{t:"Mencatatkan sekali ini saja", s:3},{t:"Mencatatkan karena sudah biasa", s:2},{t:"Ikut meminta dititipkan juga lain waktu", s:1}], ex:"Titip absen adalah kecurangan kecil yang merusak disiplin; tolak tanpa kompromi."},
{id:"TKP-240", q:"Anda melihat rekan menggunakan kendaraan dinas untuk keperluan pribadi di akhir pekan. Sikap Anda ....", opts:[{t:"Menegurnya secara pribadi dan mengingatkan aturan penggunaan aset negara", s:5},{t:"Melaporkannya kepada atasan", s:4},{t:"Mendiamkan karena bukan urusan Anda", s:3},{t:"Ikut meminjam sesekali", s:2},{t:"Memotret dan menyebarkannya", s:1}], ex:"Menegur langsung dengan baik lebih mendidik daripada mendiamkan atau mempermalukan."},
{id:"TKP-241", q:"Ada pekerjaan mendesak di luar tugas pokok Anda karena petugasnya sakit. Atasan meminta Anda menanganinya. Sikap Anda ....", opts:[{t:"Menerima dan mengerjakannya sebaik mungkin sebagai bentuk pengabdian", s:5},{t:"Menerima tetapi mengerjakannya seadanya", s:4},{t:"Meminta atasan mencari orang lain", s:3},{t:"Menolak karena bukan tugas Anda", s:2},{t:"Menerima dengan syarat ada tambahan honor", s:1}], ex:"Kesiapan membantu di luar tugas pokok saat darurat menunjukkan dedikasi ASN."},
{id:"TKP-242", q:"Atasan mengkritik cara kerja Anda di depan banyak orang. Kritiknya ada benarnya tetapi caranya mempermalukan. Anda ....", opts:[{t:"Menerima kritiknya secara profesional dan memperbaiki cara kerja", s:5},{t:"Menerima tetapi menyampaikan keberatan secara pribadi setelahnya", s:4},{t:"Membela diri di depan umum juga", s:3},{t:"Menyimpan dendam kepada atasan", s:2},{t:"Melaporkan atasan ke atasannya", s:1}], ex:"Kritik yang benar tetaplah masukan; kedewasaan terlihat dari cara menerimanya."},
{id:"TKP-243", q:"Pekerjaan menumpuk dari tiga atasan berbeda dengan tenggat yang sama. Anda ....", opts:[{t:"Menyusun prioritas, mengomunikasikan ke atasan, dan menyelesaikan satu per satu", s:5},{t:"Mengerjakan yang paling mudah dulu", s:4},{t:"Meminta salah satu atasan membatalkan tugasnya", s:3},{t:"Mengerjakan asal-asalan agar semua selesai", s:2},{t:"Pura-pura sakit agar tidak dibebani", s:1}], ex:"Manajemen prioritas dan komunikasi terbuka adalah cara profesional menangani beban berlebih."},
{id:"TKP-244", q:"Beredar kabar bohong di grup warga bahwa kelurahan memungut biaya besar untuk surat yang sebenarnya gratis. Anda ....", opts:[{t:"Memberikan klarifikasi resmi dengan data dan menyebarkannya di kanal yang sama", s:5},{t:"Menjelaskan kepada warga yang bertanya langsung", s:4},{t:"Melaporkan penyebar kabar ke polisi", s:3},{t:"Membiarkan karena nanti juga reda", s:2},{t:"Ikut menyebarkan agar viral", s:1}], ex:"Hoaks dilawan dengan klarifikasi resmi yang cepat dan berbasis fakta."},
{id:"TKP-245", q:"Anda mengetahui oknum petugas memungut biaya liar dari warga. Oknum itu senior dan berpengaruh. Tindakan Anda ....", opts:[{t:"Melaporkan melalui kanal resmi seperti saber pungli atau atasan", s:5},{t:"Menegur oknum tersebut secara pribadi", s:4},{t:"Mendiamkan karena takut", s:3},{t:"Ikut menikmati hasilnya", s:1},{t:"Menyebarkan ke media sosial", s:2}], ex:"Melaporkan pungli lewat jalur resmi adalah keberanian yang dilindungi."},
{id:"TKP-246", q:"Anda diberi tugas menyusun laporan yang teknis dan belum pernah Anda kerjakan. Tenggatnya seminggu. Sikap Anda ....", opts:[{t:"Mempelajari dari contoh dan bertanya kepada yang berpengalaman hingga bisa", s:5},{t:"Mencoba mengerjakan sebisanya", s:4},{t:"Meminta tugas diganti yang lebih mudah", s:3},{t:"Menunda sampai mendekati tenggat", s:2},{t:"Menyalin laporan lama dan mengganti angkanya", s:1}], ex:"Tugas sulit adalah kesempatan belajar; kemauan belajar mengalahkan keterbatasan awal."},
{id:"TKP-247", q:"Kantor menerapkan jam kerja fleksibel, tetapi Anda melihat rekan menyalahgunakannya untuk sering terlambat. Anda ....", opts:[{t:"Tetap disiplin dan menjadi teladan, serta mengingatkan rekan bila perlu", s:5},{t:"Tetap disiplin tanpa mengurusi rekan", s:4},{t:"Ikut longgar karena atasan tidak menegur", s:3},{t:"Melaporkan rekan ke atasan", s:2},{t:"Menghasut rekan lain ikut longgar", s:1}], ex:"Disiplin adalah komitmen pribadi, bukan ikut-ikutan; teladan lebih kuat dari teguran."},
{id:"TKP-248", q:"Dokumen penting yang Anda pegang hilang menjelang rapat. Anda sudah mencari ke mana-mana. Tindakan Anda ....", opts:[{t:"Melapor kepada atasan, menjelaskan, dan segera membuat penggantinya", s:5},{t:"Membuat pengganti diam-diam", s:4},{t:"Menyalahkan rekan yang terakhir memegang", s:3},{t:"Berharap tidak ada yang sadar", s:2},{t:"Membatalkan rapat dengan alasan lain", s:1}], ex:"Kejujuran mengakui kehilangan plus solusi cepat lebih baik daripada menutupi."},
{id:"TKP-249", q:"Perusahaan milik keluarga Anda ikut tender pengadaan di kantor Anda. Anda ditunjuk jadi panitia. Sikap Anda ....", opts:[{t:"Mengundurkan diri dari kepanitiaan untuk menghindari konflik kepentingan", s:5},{t:"Tetap jadi panitia tetapi bersikap netral", s:4},{t:"Meminta keluarga mundur dari tender", s:3},{t:"Tetap jadi panitia dan memenangkan keluarga", s:2},{t:"Merahasiakan hubungan keluarga", s:1}], ex:"Menghindari konflik kepentingan sejak awal adalah standar integritas tertinggi."},
{id:"TKP-250", q:"Anda yakin keputusan atasan keliru berdasarkan data yang Anda miliki. Menyampaikannya berisiko dianggap membantah. Anda ....", opts:[{t:"Menyampaikan data dan pandangan secara santun dalam forum yang tepat", s:5},{t:"Menyampaikan lewat rekan yang dekat dengan atasan", s:4},{t:"Diam dan menjalankan keputusan yang keliru", s:3},{t:"Menentang di depan umum", s:2},{t:"Membocorkan ke pihak luar", s:1}], ex:"Loyalitas sejati termasuk berani memberi masukan benar dengan cara yang tepat."},
{id:"TKP-251", q:"Pelayanan warga belum selesai padahal jam kerja hampir habis dan tidak ada uang lembur. Anda ....", opts:[{t:"Menyelesaikan pelayanan warga yang sudah antre hingga tuntas", s:5},{t:"Melayani yang paling mendesak saja", s:4},{t:"Menutup tepat waktu sesuai jam kerja", s:3},{t:"Mengeluh kepada warga tentang tidak adanya lembur", s:2},{t:"Pulang dan mematikan lampu", s:1}], ex:"Tanggung jawab pelayanan mengalahkan perhitungan jam; warga yang sudah antre wajib dituntaskan."},
{id:"TKP-252", q:"Anda dimutasi ke bidang yang sama sekali baru dan asing bagi Anda. Sikap Anda ....", opts:[{t:"Menerima dengan ikhlas dan belajar cepat agar segera produktif", s:5},{t:"Menerima sambil perlahan beradaptasi", s:4},{t:"Meminta atasan mempertimbangkan ulang", s:3},{t:"Menjalani dengan setengah hati", s:2},{t:"Mencari koneksi agar mutasi dibatalkan", s:1}], ex:"Mutasi adalah amanah; adaptasi cepat menunjukkan profesionalisme ASN."},
{id:"TKP-253", q:"Rekan kerja menyebarkan aib pribadi atasan di grup WhatsApp kantor. Ia mengajak Anda menanggapi. Anda ....", opts:[{t:"Tidak ikut serta dan mengingatkannya bahwa itu tidak pantas", s:5},{t:"Diam dan tidak menanggapi", s:4},{t:"Ikut membaca tetapi tidak berkomentar", s:3},{t:"Ikut menanggapi agar akrab", s:2},{t:"Menyebarkan lebih luas", s:1}], ex:"Menjaga martabat orang lain, termasuk atasan, adalah etika kerja."},
{id:"TKP-254", q:"Kegiatan selesai dan ada sisa anggaran yang lumayan. Bendahara menyarankan menggunakannya untuk jalan-jalan tim. Anda ....", opts:[{t:"Menolak dan memastikan sisa anggaran dikembalikan sesuai aturan", s:5},{t:"Mengusulkan dikembalikan ke kas", s:4},{t:"Diam mengikuti keputusan bersama", s:3},{t:"Ikut jalan-jalan karena sudah disetujui bersama", s:2},{t:"Mengusulkan dibagi rata", s:1}], ex:"Sisa anggaran adalah uang negara; mengembalikannya adalah kewajiban."},
{id:"TKP-255", q:"Anda diminta menilai kinerja bawahan untuk kenaikan pangkat. Salah satunya kerabat dekat Anda yang kinerjanya biasa saja. Anda ....", opts:[{t:"Menilai objektif berdasarkan fakta kinerja", s:5},{t:"Memberi nilai sedikit lebih tinggi karena hubungan baik", s:4},{t:"Menyerahkan penilaian ke atasan", s:3},{t:"Memberi nilai tinggi agar ia naik pangkat", s:2},{t:"Memberi nilai rendah ke pesaingnya", s:1}], ex:"Objektivitas penilaian adalah keadilan bagi semua bawahan."},
{id:"TKP-256", q:"Anda diberi wewenang menandatangani surat-surat tertentu saat atasan dinas. Wewenang itu menggoda untuk disalahgunakan. Sikap Anda ....", opts:[{t:"Menggunakannya tepat sesuai batas dan mencatat setiap penggunaan", s:5},{t:"Menggunakannya hanya bila perlu", s:4},{t:"Menggunakannya untuk membantu kerabat juga", s:3},{t:"Menolak wewenang karena takut salah", s:2},{t:"Menggunakannya untuk kepentingan pribadi", s:1}], ex:"Amanah wewenang dijaga dengan batasan jelas dan pencatatan."},
{id:"TKP-257", q:"Menjelang pilkada, tim sukses salah satu calon menekan Anda untuk memihak. Mereka menjanjikan jabatan. Anda ....", opts:[{t:"Menolak dan menjaga netralitas sebagai ASN", s:5},{t:"Bersikap netral tanpa menanggapi tawaran", s:4},{t:"Berpura-pura mendukung agar aman", s:3},{t:"Diam-diam mendukung", s:2},{t:"Terang-terangan berkampanye", s:1}], ex:"Netralitas ASN adalah harga mati dalam demokrasi."},
{id:"TKP-258", q:"Anda akan serah terima jabatan. Arsip dan dokumen di meja Anda berantakan dan tidak terdokumentasi. Tindakan Anda ....", opts:[{t:"Merapikan dan mendokumentasikan semuanya sebelum serah terima", s:5},{t:"Menjelaskan secara lisan kepada pengganti", s:4},{t:"Menyerahkan apa adanya", s:3},{t:"Membawa pulang dokumen penting", s:2},{t:"Membuang yang dianggap tidak penting", s:1}], ex:"Serah terima yang rapi adalah tanggung jawab profesional hingga akhir masa tugas."},
{id:"TKP-259", q:"Vendor rekanan mengundang Anda ke jamuan mewah setelah proyek selesai. Tidak ada pembahasan bisnis katanya. Anda ....", opts:[{t:"Menolak dengan halus untuk menghindari gratifikasi terselubung", s:5},{t:"Hadir tetapi tidak menerima bingkisan", s:4},{t:"Hadir karena proyek sudah selesai", s:3},{t:"Hadir dan membawa keluarga", s:2},{t:"Meminta diundang lebih sering", s:1}], ex:"Menjaga jarak dari rekanan mencegah gratifikasi dalam bentuk apa pun."},
{id:"TKP-260", q:"Anda harus mengambil keputusan berisiko tinggi dengan informasi terbatas dan waktu mepet. Sikap Anda ....", opts:[{t:"Mengkaji cepat, berkonsultasi, lalu memutuskan dengan berani dan bertanggung jawab", s:5},{t:"Memutuskan berdasarkan intuisi", s:4},{t:"Menunda keputusan sampai informasi lengkap", s:3},{t:"Melempar keputusan ke atasan", s:2},{t:"Tidak memutuskan apa-apa", s:1}], ex:"Keberanian memutuskan dengan kajian dan tanggung jawab adalah kepemimpinan."},
{id:"TKP-261", q:"Bawahan Anda melakukan kesalahan yang merugikan warga. Ia ketakutan akan dimarahi. Tindakan Anda ....", opts:[{t:"Membina dan membimbingnya memperbaiki, bukan memaki", s:5},{t:"Menegurnya tegas tetapi memberi solusi", s:4},{t:"Melaporkannya ke atasan untuk diberi sanksi", s:3},{t:"Memakinya di depan rekan lain", s:2},{t:"Membiarkannya menanggung sendiri", s:1}], ex:"Pemimpin membina bawahan yang salah, bukan menghancurkannya."},
{id:"TKP-262", q:"Target kinerja unit Anda triwulan ini tidak tercapai. Dalam evaluasi, Anda ....", opts:[{t:"Mengakui, menganalisis penyebab, dan menyusun rencana perbaikan", s:5},{t:"Menjelaskan kendala yang dihadapi", s:4},{t:"Menyalahkan kondisi eksternal", s:3},{t:"Menyalahkan anggota tim", s:2},{t:"Memanipulasi data capaian", s:1}], ex:"Kegagalan diakui dan dianalisis; itulah awal perbaikan kinerja."},
{id:"TKP-263", q:"Usulan inovasi Anda ditolak atasan tanpa alasan jelas. Anda yakin inovasinya bagus. Sikap Anda ....", opts:[{t:"Mengajukan kembali dengan data dan kajian yang lebih kuat", s:5},{t:"Menerima keputusan atasan", s:4},{t:"Menerapkan diam-diam", s:3},{t:"Mengeluh kepada rekan-rekan", s:2},{t:"Berhenti berinovasi", s:1}], ex:"Inovasi diperjuangkan dengan data, bukan emosi atau jalan pintas."},
{id:"TKP-264", q:"Anda kurang enak badan tetapi ada pelayanan warga yang hanya Anda yang bisa menangani hari itu. Anda ....", opts:[{t:"Tetap masuk dengan menjaga kondisi, atau mengatur pengganti resmi bila benar-benar tidak mampu", s:5},{t:"Masuk dan melayani seperti biasa", s:4},{t:"Izin resmi dan memberitahu atasan", s:3},{t:"Masuk tetapi melayani seadanya", s:2},{t:"Tidak masuk tanpa kabar", s:1}], ex:"Tanggung jawab diimbangi kejujuran kondisi; yang penting pelayanan tidak terbengkalai."},
{id:"TKP-265", q:"Anda menemukan ijazah pelamar tenaga honorer yang tampak palsu. Ia sudah lolos seleksi berkas. Tindakan Anda ....", opts:[{t:"Melaporkan temuan kepada panitia/atasan untuk diverifikasi", s:5},{t:"Menanyakan langsung kepada pelamar", s:4},{t:"Mendiamkan karena bukan wewenang Anda", s:3},{t:"Meloloskan karena kasihan", s:2},{t:"Memeras pelamar agar tidak dilaporkan", s:1}], ex:"Temuan dokumen palsu wajib dilaporkan; integritas seleksi tidak bisa ditawar."},
{id:"TKP-266", q:"Atasan meminta Anda menutupi kesalahannya dalam laporan kepada inspektorat. Ia berjanji akan membalas kebaikan Anda. Anda ....", opts:[{t:"Menolak dengan halus dan menyarankan keterbukaan disertai rencana perbaikan", s:5},{t:"Menolak tetapi tidak memberi saran", s:4},{t:"Mengikuti permintaan atasan", s:3},{t:"Menutupi dengan imbalan", s:1},{t:"Malah membocorkan ke inspektorat", s:2}], ex:"Loyalitas tidak berarti menutupi kesalahan; kejujuran melindungi institusi."},
{id:"TKP-267", q:"Tim Anda mendapat penghargaan. Atasan menyebut nama Anda sebagai yang paling berjasa, padahal itu kerja tim. Anda ....", opts:[{t:"Menyampaikan bahwa itu hasil kerja seluruh tim", s:5},{t:"Menerima dengan rendah hati", s:4},{t:"Diam saja menikmati pujian", s:3},{t:"Menambahkan jasa-jasa Anda", s:2},{t:"Menjatuhkan rekan agar Anda sendiri yang dipuji", s:1}], ex:"Kredit keberhasilan milik tim; kerendahan hati memperkuat kekompakan."},
{id:"TKP-268", q:"Anda ditugaskan ke daerah terpencil dengan fasilitas terbatas selama setahun. Keluarga keberatan. Sikap Anda ....", opts:[{t:"Menerima sebagai amanah dan menjalankannya dengan ikhlas", s:5},{t:"Menerima sambil mencari solusi untuk keluarga", s:4},{t:"Meminta penundaan penugasan", s:3},{t:"Mencari cara agar dibatalkan", s:2},{t:"Menolak mentah-mentah", s:1}], ex:"Penugasan adalah sumpah jabatan; keikhlasan menjalankannya adalah pengabdian."},
{id:"TKP-269", q:"Anda diberi kesempatan mengelola dana kegiatan yang besar tanpa pengawasan ketat. Godaan untuk mengambil sedikit muncul. Anda ....", opts:[{t:"Mengelola dengan jujur dan transparan, mengingat sumpah jabatan", s:5},{t:"Mengelola apa adanya tanpa tergoda", s:4},{t:"Mengambil sedikit karena tidak akan ketahuan", s:3},{t:"Mengambil banyak mumpung bisa", s:2},{t:"Mengajak rekan berbagi", s:1}], ex:"Integritas justru diuji saat tidak ada yang mengawasi."},
{id:"TKP-270", q:"Anda akan pensiun bulan depan. Arsip kerja Anda menumpuk tidak tertata. Tindakan Anda ....", opts:[{t:"Menata dan mendokumentasikannya agar mudah dilanjutkan pengganti", s:5},{t:"Menjelaskan isinya secara lisan kepada pengganti", s:4},{t:"Membiarkannya karena bukan urusan Anda lagi", s:3},{t:"Membawa pulang yang dianggap penting", s:2},{t:"Membuang semuanya", s:1}], ex:"Tanggung jawab profesional berlaku hingga hari terakhir masa tugas."},
{id:"TKP-271", q:"Rekan satu tim Anda kewalahan karena pekerjaannya menumpuk sementara Anda sudah selesai lebih awal. Sikap Anda ....", opts:[{t:"Menawarkan bantuan dan mengerjakan sebagian tugasnya bersama", s:5},{t:"Membantunya bila ia meminta", s:4},{t:"Memberinya semangat tanpa membantu", s:3},{t:"Membiarkannya karena itu tanggung jawabnya", s:2},{t:"Melaporkannya ke atasan sebagai tidak kompeten", s:1}], ex:"Solidaritas tim berarti ringan tangan membantu, bukan menunggu diminta."},
{id:"TKP-272", q:"Dalam rapat, pendapat Anda ditolak dan keputusan diambil mengikuti usulan rekan lain yang menurut Anda kurang tepat. Anda ....", opts:[{t:"Mendukung keputusan bersama dan melaksanakannya dengan maksimal", s:5},{t:"Menerima keputusan meski kurang setuju", s:4},{t:"Meminta voting ulang", s:3},{t:"Menjalankan dengan setengah hati", s:2},{t:"Menyabotase keputusan tersebut", s:1}], ex:"Kedewasaan tim adalah mendukung keputusan bersama meski berbeda pendapat."},
{id:"TKP-273", q:"Seorang pegawai baru di unit Anda terlihat bingung dan canggung di minggu pertamanya. Tindakan Anda ....", opts:[{t:"Aktif membimbing dan mengenalkannya pada alur kerja serta rekan-rekan", s:5},{t:"Menjawab bila ia bertanya", s:4},{t:"Membiarkannya belajar sendiri", s:3},{t:"Menyuruhnya membaca arsip lama", s:2},{t:"Menganggapnya beban tim", s:1}], ex:"Membimbing anggota baru mempercepat ia produktif dan membangun budaya baik."},
{id:"TKP-274", q:"Tim Anda gagal mencapai target dan atasan meminta evaluasi. Dalam forum, Anda ....", opts:[{t:"Menganalisis bersama akar masalahnya dan menyusun perbaikan tanpa saling menyalahkan", s:5},{t:"Mengakui kegagalan dan berjanji memperbaiki", s:4},{t:"Menjelaskan kendala yang dihadapi tim", s:3},{t:"Menunjuk anggota yang paling bersalah", s:2},{t:"Menyalahkan atasan yang targetnya tidak realistis", s:1}], ex:"Evaluasi yang sehat fokus pada solusi, bukan kambing hitam."},
{id:"TKP-275", q:"Atasan memarahi seluruh tim karena satu kesalahan, termasuk Anda yang tidak terlibat. Sikap Anda ....", opts:[{t:"Menerima dengan lapang dan membantu memastikan kesalahan tidak terulang", s:5},{t:"Menerima meski merasa tidak adil", s:4},{t:"Membela diri bahwa Anda tidak terlibat", s:3},{t:"Balik memarahi atasan", s:2},{t:"Menghasut tim melawan atasan", s:1}], ex:"Tanggung jawab kolektif tim kadang berarti menerima teguran bersama dengan dewasa."},
{id:"TKP-276", q:"Ide yang Anda sampaikan di rapat dipakai rekan sebagai idenya dan ia mendapat pujian atasan. Anda ....", opts:[{t:"Mengikhlaskan demi kemajuan tim dan tetap berkontribusi", s:5},{t:"Diam tetapi sedikit kecewa", s:4},{t:"Mengklarifikasi di depan atasan bahwa itu ide Anda", s:3},{t:"Menuntut pengakuan", s:2},{t:"Berhenti memberi ide", s:1}], ex:"Kontribusi untuk tim lebih mulia daripada berebut pengakuan."},
{id:"TKP-277", q:"Jadwal piket Anda bentrok dengan acara keluarga penting yang sudah direncanakan lama. Anda ....", opts:[{t:"Berunding baik-baik dengan rekan untuk bertukar jadwal", s:5},{t:"Meminta izin resmi kepada atasan", s:4},{t:"Tetap piket dan membatalkan acara keluarga", s:3},{t:"Tidak masuk piket tanpa kabar", s:2},{t:"Menyuruh rekan menggantikan tanpa persetujuan", s:1}], ex:"Benturan jadwal diselesaikan dengan komunikasi dan tukar-menukar yang adil."},
{id:"TKP-278", q:"Rekan kerja sakit dan tugas pentingnya dilimpahkan kepada Anda di saat pekerjaan Anda sendiri padat. Anda ....", opts:[{t:"Menerima dan mengatur prioritas agar keduanya tertangani", s:5},{t:"Menerima dan mengerjakan sebisanya", s:4},{t:"Meminta atasan mencari orang lain", s:3},{t:"Menolak karena sudah padat", s:2},{t:"Menerima tetapi mengerjakannya asal-asalan", s:1}], ex:"Menolong rekan yang sakit adalah empati; mengaturnya adalah profesionalisme."},
{id:"TKP-279", q:"Terjadi kesalahpahaman dengan bidang lain soal pembagian tugas kegiatan bersama. Masing-masing merasa benar. Anda ....", opts:[{t:"Mengajak duduk bersama mengklarifikasi dan menyepakati pembagian yang jelas", s:5},{t:"Mengalah demi kelancaran kegiatan", s:4},{t:"Bersikeras pada pemahaman Anda", s:3},{t:"Melaporkan ke pimpinan untuk diputuskan", s:2},{t:"Menarik diri dari kegiatan bersama", s:1}], ex:"Miskomunikasi antar unit diselesaikan dengan dialog, bukan ego sektoral."},
{id:"TKP-280", q:"Kantor Anda harus bekerja sama dengan dinas lain dalam program besar, tetapi koordinasinya macet. Sebagai anggota tim, Anda ....", opts:[{t:"Aktif membangun komunikasi dan menawarkan solusi koordinasi", s:5},{t:"Mengikuti alur koordinasi yang ada", s:4},{t:"Menunggu arahan pimpinan", s:3},{t:"Menyalahkan dinas lain yang tidak kooperatif", s:2},{t:"Menarik diri dari program", s:1}], ex:"Kerja sama lintas instansi butuh inisiatif, bukan sekadar menunggu."},
{id:"TKP-281", q:"Bawahan Anda membantah instruksi di depan rekan-rekannya karena merasa caranya lebih baik. Tindakan Anda ....", opts:[{t:"Mendengarkan masukannya, lalu menjelaskan keputusan dengan bijak secara pribadi", s:5},{t:"Menegur dan memintanya menjalankan instruksi", s:4},{t:"Membiarkannya memakai caranya", s:3},{t:"Mempermalukannya balik di depan umum", s:2},{t:"Memberinya sanksi berat", s:1}], ex:"Pemimpin yang baik mendengar dulu, menegur dengan cara yang menjaga martabat."},
{id:"TKP-282", q:"Rekan kerja Anda bekerja lamban sehingga tugas tim sering terlambat. Ia sebenarnya mau belajar. Anda ....", opts:[{t:"Membantunya meningkatkan kemampuan tanpa merendahkannya", s:5},{t:"Membagi tugas sesuai kemampuannya", s:4},{t:"Melaporkannya ke atasan", s:3},{t:"Mengerjakan bagiannya diam-diam", s:2},{t:"Mengolok-oloknya di depan tim", s:1}], ex:"Membina rekan yang lamban lebih membangun daripada mengeluh atau merendahkan."},
{id:"TKP-283", q:"Pembagian tugas dalam tim Anda terasa tidak adil; Anda mendapat porsi terbanyak. Sikap Anda ....", opts:[{t:"Menyampaikannya secara baik-baik kepada koordinator dengan data", s:5},{t:"Menerima dan mengerjakannya", s:4},{t:"Protes keras di depan tim", s:3},{t:"Mogok mengerjakan sebagian", s:2},{t:"Menghasut rekan lain ikut protes", s:1}], ex:"Ketidakadilan disampaikan lewat jalur yang tepat dengan cara santun."},
{id:"TKP-284", q:"Rapat koordinasi molor dua jam dari jadwal dan Anda mulai lelah, padahal agenda penting belum dibahas. Anda ....", opts:[{t:"Tetap fokus dan berkontribusi hingga agenda penting selesai", s:5},{t:"Tetap mengikuti dengan sabar", s:4},{t:"Mengusulkan rapat dilanjut besok", s:3},{t:"Izin keluar diam-diam", s:2},{t:"Protes dan meninggalkan rapat", s:1}], ex:"Komitmen pada agenda penting mengalahkan kelelahan pribadi."},
{id:"TKP-285", q:"Tim Anda mendapat apresiasi dari pimpinan daerah atas program yang sukses. Dalam syukuran tim, Anda ....", opts:[{t:"Merayakannya bersama dan mengapresiasi kontribusi setiap anggota", s:5},{t:"Ikut bergembira", s:4},{t:"Biasa saja karena sudah tugas", s:3},{t:"Mengungkit jasa Anda paling besar", s:2},{t:"Tidak hadir karena tidak suka keramaian", s:1}], ex:"Merayakan keberhasilan bersama memperkuat ikatan tim."},
{id:"TKP-286", q:"Dua rekan kerja berselisih paham hingga tidak bertegur sapa, dan pekerjaan tim terganggu. Sebagai rekan mereka, Anda ....", opts:[{t:"Menjadi penengah dan membantu keduanya berdamai", s:5},{t:"Menasihati keduanya secara terpisah", s:4},{t:"Melaporkan ke atasan", s:3},{t:"Memihak salah satu yang benar", s:2},{t:"Membiarkan karena urusan mereka", s:1}], ex:"Inisiatif mendamaikan rekan menyelamatkan kekompakan tim."},
{id:"TKP-287", q:"Atasan meminta laporan yang biasanya seminggu dikumpulkan besok pagi. Data belum lengkap. Anda ....", opts:[{t:"Mengerjakan prioritas malam ini dengan data terbaik yang ada plus catatan", s:5},{t:"Lembur mengerjakannya", s:4},{t:"Meminta atasan menunda tenggat", s:3},{t:"Menolak karena tidak masuk akal", s:2},{t:"Mengarang data agar terlihat lengkap", s:1}], ex:"Permintaan mendesak dijawab dengan kerja maksimal dan kejujuran data."},
{id:"TKP-288", q:"Rekan kerja curhat tentang masalah rumah tangganya yang memengaruhi kinerjanya. Ia meminta saran Anda. Sikap Anda ....", opts:[{t:"Mendengarkan dengan empati dan memberinya semangat serta saran bijak", s:5},{t:"Mendengarkan dan menyarankan konsultasi profesional", s:4},{t:"Mendengarkan sekadarnya", s:3},{t:"Menyuruhnya tidak membawa masalah pribadi ke kantor", s:2},{t:"Menyebarkan curhatannya ke rekan lain", s:1}], ex:"Empati pada rekan yang kesulitan adalah kemanusiaan; kerahasiaan wajib dijaga."},
{id:"TKP-289", q:"Dalam tugas kelompok, satu anggota hampir tidak berkontribusi sementara tenggat dekat. Anda ....", opts:[{t:"Mengajaknya bicara baik-baik dan membagi peran yang sesuai kemampuannya", s:5},{t:"Membagi ulang tugas agar tetap selesai", s:4},{t:"Melaporkannya ke koordinator", s:3},{t:"Mengerjakan bagiannya tanpa bicara", s:2},{t:"Mengeluarkannya dari kelompok", s:1}], ex:"Anggota pasif dirangkul dan diberi peran, bukan dibuang atau dibiarkan."},
{id:"TKP-290", q:"Anda serah terima shift piket dengan rekan. Ada beberapa hal penting yang harus ia ketahui. Tindakan Anda ....", opts:[{t:"Menginformasikan lengkap secara tertulis dan lisan", s:5},{t:"Menjelaskan hal-hal pentingnya", s:4},{t:"Menitipkan catatan singkat", s:3},{t:"Menganggap ia sudah tahu", s:2},{t:"Langsung pulang tanpa serah terima", s:1}], ex:"Serah terima yang lengkap mencegah kesalahan pada shift berikutnya."},
{id:"TKP-291", q:"Rekan satu tim berbeda suku dan agama dengan Anda. Dalam kerja sama sehari-hari, Anda ....", opts:[{t:"Menghormati dan bekerja sama secara setara tanpa membeda-bedakan", s:5},{t:"Bekerja sama secara profesional", s:4},{t:"Menjaga jarak agar tidak salah paham", s:3},{t:"Hanya bekerja sama bila terpaksa", s:2},{t:"Menolak satu tim dengannya", s:1}], ex:"Keberagaman adalah kekuatan tim bila disikapi dengan saling menghormati."},
{id:"TKP-292", q:"Kantor mengadakan kerja bakti membersihkan lingkungan. Anda sedang banyak pekerjaan. Sikap Anda ....", opts:[{t:"Ikut aktif dan mengatur pekerjaan agar keduanya berjalan", s:5},{t:"Ikut sebentar lalu kembali bekerja", s:4},{t:"Izin tidak ikut karena pekerjaan", s:3},{t:"Pura-pura tidak tahu ada kerja bakti", s:2},{t:"Menyuruh bawahan mewakili", s:1}], ex:"Partisipasi dalam kegiatan bersama menunjukkan kebersamaan, bukan sekadar formalitas."},
{id:"TKP-293", q:"Tim baru dibentuk dengan anggota dari berbagai unit yang belum saling kenal. Sebagai anggota, Anda ....", opts:[{t:"Aktif membangun keakraban dan kepercayaan antar anggota", s:5},{t:"Bersikap ramah dan kooperatif", s:4},{t:"Menunggu orang lain memulai", s:3},{t:"Bekerja sendiri-sendiri saja", s:2},{t:"Membentuk kubu dengan yang sudah dikenal", s:1}], ex:"Tim baru butuh inisiatif membangun kepercayaan agar cepat solid."},
{id:"TKP-294", q:"Dalam evaluasi 360 derajat, rekan memberi masukan bahwa Anda kurang responsif. Tanggapan Anda ....", opts:[{t:"Menerima dengan terbuka dan memperbaiki diri", s:5},{t:"Menerima dan introspeksi", s:4},{t:"Membela diri bahwa Anda sudah responsif", s:3},{t:"Mencari siapa yang memberi masukan buruk", s:2},{t:"Menolak hasil evaluasi", s:1}], ex:"Masukan, meski pahit, adalah cermin untuk berkembang."},
{id:"TKP-295", q:"Rekan seangkatan dipromosikan mendahului Anda. Anda merasa kinerja Anda tidak kalah. Sikap Anda ....", opts:[{t:"Memberi selamat dengan tulus dan introspeksi untuk meningkatkan diri", s:5},{t:"Memberi selamat meski kecewa", s:4},{t:"Mempertanyakan keputusan ke atasan", s:3},{t:"Iri dan menjauhinya", s:2},{t:"Menyebar kabar ia naik karena koneksi", s:1}], ex:"Kedewasaan terlihat dari kemampuan memberi selamat dan memperbaiki diri."},
{id:"TKP-296", q:"Anda harus bekerja di bawah atasan yang terkenal galak dan perfeksionis. Strategi Anda ....", opts:[{t:"Bekerja profesional, teliti, dan menjaga komunikasi baik", s:5},{t:"Berusaha memenuhi standarnya", s:4},{t:"Menghindari interaksi seminimal mungkin", s:3},{t:"Mengeluh kepada rekan-rekan", s:2},{t:"Meminta pindah unit", s:1}], ex:"Atasan yang menuntut justru melatih kita menjadi lebih baik bila disikapi positif."},
{id:"TKP-297", q:"Dinas lain meminta bantuan data yang hanya unit Anda yang punya, dengan tenggat mendesak. Anda ....", opts:[{t:"Merespons cepat dan membantu menyediakan data yang diminta", s:5},{t:"Membantu setelah pekerjaan sendiri selesai", s:4},{t:"Meminta surat resmi dulu", s:3},{t:"Menolak karena sibuk", s:2},{t:"Memberi data seadanya", s:1}], ex:"Responsif membantu unit lain memperlancar kerja pemerintahan secara keseluruhan."},
{id:"TKP-298", q:"Warga mengajak gotong royong memperbaiki jalan lingkungan dan meminta dukungan kelurahan. Anda ....", opts:[{t:"Mendukung aktif dan membantu mengoordinasikan", s:5},{t:"Memberi dukungan moral", s:4},{t:"Menghadiri pembukaannya saja", s:3},{t:"Menolak karena bukan program resmi", s:2},{t:"Mengabaikan ajakan", s:1}], ex:"Mendukung swadaya warga memperkuat kemitraan pemerintah dan masyarakat."},
{id:"TKP-299", q:"Rekan membuat kesalahan fatal dalam laporan yang sudah dikirim ke pimpinan. Ia panik. Anda ....", opts:[{t:"Membantunya menyusun perbaikan dan klarifikasi kepada pimpinan", s:5},{t:"Membantunya memperbaiki laporannya", s:4},{t:"Menyarankannya melapor sendiri", s:3},{t:"Menjauh agar tidak terseret", s:2},{t:"Memanfaatkan untuk menjatuhkannya", s:1}], ex:"Menolong rekan memperbaiki kesalahan fatal adalah solidaritas sejati."},
{id:"TKP-300", q:"Rekan dekat Anda mutasi ke daerah lain. Di acara perpisahannya, Anda ....", opts:[{t:"Memberi kesan baik dan menjaga silaturahmi", s:5},{t:"Menghadiri dan mengucapkan selamat", s:4},{t:"Hadir sebentar", s:3},{t:"Tidak hadir karena sibuk", s:2},{t:"Senang karena pesaing berkurang", s:1}], ex:"Menghargai kebersamaan hingga akhir membangun jaringan silaturahmi yang baik."},
{id:"TKP-301", q:"Seorang warga berbeda keyakinan meminta bantuan pengurusan yang sama seperti warga lain. Beberapa tetangganya berbisik sinis. Anda ....", opts:[{t:"Melayaninya dengan sama baiknya karena hak setiap warga setara", s:5},{t:"Melayaninya secara profesional", s:4},{t:"Melayaninya cepat agar tidak jadi perhatian", s:3},{t:"Memintanya datang saat sepi", s:2},{t:"Menunda pelayanannya", s:1}], ex:"Kesetaraan layanan tanpa memandang keyakinan adalah amanat konstitusi."},
{id:"TKP-302", q:"Acara adat masyarakat setempat bentrok dengan jadwal kegiatan dinas yang sudah ditetapkan. Warga meminta penyesuaian. Anda ....", opts:[{t:"Mengoordinasikan penyesuaian jadwal dengan menghormati adat setempat", s:5},{t:"Menghadiri acara adat sebagai bentuk penghargaan", s:4},{t:"Tetap pada jadwal dinas", s:3},{t:"Mengabaikan permintaan warga", s:2},{t:"Melarang acara adat karena mengganggu", s:1}], ex:"Menghormati adat istiadat memperkuat legitimasi pemerintah di mata warga."},
{id:"TKP-303", q:"Seorang warga tua hanya fasih berbahasa daerah dan tidak paham bahasa Indonesia. Ia butuh penjelasan prosedur. Anda ....", opts:[{t:"Berusaha menjelaskan dengan bahasa daerah yang Anda bisa atau meminta bantuan yang bisa", s:5},{t:"Menjelaskan perlahan dengan bahasa sederhana", s:4},{t:"Memintanya membawa penerjemah", s:3},{t:"Memberinya brosur berbahasa Indonesia", s:2},{t:"Menolak melayani karena kendala bahasa", s:1}], ex:"Bahasa tidak boleh jadi penghalang hak warga atas pelayanan."},
{id:"TKP-304", q:"Tradisi lokal melarang aktivitas tertentu di hari tertentu, padahal ada pelayanan mendesak yang harus jalan. Anda ....", opts:[{t:"Mencari jalan tengah dengan musyawarah bersama tokoh adat", s:5},{t:"Menghormati tradisi dan menunda yang tidak mendesak", s:4},{t:"Tetap menjalankan pelayanan seperti biasa", s:3},{t:"Mengabaikan tradisi", s:2},{t:"Melarang tradisi tersebut", s:1}], ex:"Musyawarah dengan tokoh adat menemukan solusi yang menghormati keduanya."},
{id:"TKP-305", q:"Terjadi gesekan antara warga pendatang dan warga asli soal penggunaan fasilitas umum. Keduanya mengadu ke kelurahan. Anda ....", opts:[{t:"Memediasi dengan adil tanpa memihak kelompok mana pun", s:5},{t:"Membuat aturan penggunaan yang adil", s:4},{t:"Membela warga asli sebagai tuan rumah", s:3},{t:"Membela pendatang yang minoritas", s:2},{t:"Membiarkan mereka menyelesaikan sendiri", s:1}], ex:"Aparat kelurahan harus netral dan adil bagi semua warga tanpa kecuali."},
{id:"TKP-306", q:"Kantor akan mengadakan perayaan keagamaan. Pegawai berbeda keyakinan merasa tidak dilibatkan. Sikap Anda ....", opts:[{t:"Mengusulkan perayaan yang inklusif atau memfasilitasi semua keyakinan", s:5},{t:"Mengajak mereka berpartisipasi sebagai toleransi", s:4},{t:"Membiarkan mereka tidak ikut", s:3},{t:"Memaksa semua ikut", s:2},{t:"Membatalkan perayaan", s:1}], ex:"Keberagaman keyakinan di kantor dikelola dengan inklusivitas, bukan pemaksaan."},
{id:"TKP-307", q:"Dalam acara resmi kantor, hidangan yang disajikan tidak memperhatikan pantangan sebagian pegawai. Anda panitia. Tindakan Anda ....", opts:[{t:"Memastikan tersedia pilihan yang sesuai untuk semua", s:5},{t:"Menambahkan menu alternatif", s:4},{t:"Membiarkan karena sudah dipesan", s:3},{t:"Menyuruh yang berpantangan membawa sendiri", s:2},{t:"Menganggapnya berlebihan", s:1}], ex:"Perhatian pada detail keberagaman menunjukkan penghormatan yang tulus."},
{id:"TKP-308", q:"Seorang pegawai memakai pakaian adat daerahnya di acara resmi dan menjadi bahan olokan rekan. Anda ....", opts:[{t:"Menegur pengolok dan mengapresiasi kebanggaan budaya rekan tersebut", s:5},{t:"Membela rekan tersebut", s:4},{t:"Mendiamkan karena hanya bercanda", s:3},{t:"Ikut tertawa agar akrab", s:2},{t:"Menyarankan ia tidak memakai lagi", s:1}], ex:"Kebanggaan budaya harus dilindungi dari ejekan dalam bentuk apa pun."},
{id:"TKP-309", q:"Tokoh adat mengundang perangkat kelurahan dalam musyawarah adat penting. Kehadiran Anda ....", opts:[{t:"Menghadiri dengan hormat sebagai bentuk dukungan", s:5},{t:"Mengirim perwakilan", s:4},{t:"Hadir bila sempat", s:3},{t:"Menolak karena bukan agenda resmi", s:2},{t:"Mengabaikan undangan", s:1}], ex:"Menghadiri musyawarah adat mempererat kemitraan pemerintah dan masyarakat adat."},
{id:"TKP-310", q:"Dua kelompok warga berselisih soal batas tanah dan hampir bentrok fisik. Anda diminta menengahi. Tindakan Anda ....", opts:[{t:"Memediasi secara netral dengan data dan mengajak musyawarah", s:5},{t:"Memanggil kedua belah pihak untuk dialog", s:4},{t:"Menyerahkan ke polisi", s:3},{t:"Memihak yang punya bukti lebih kuat", s:2},{t:"Membiarkan sampai ada korban", s:1}], ex:"Mediasi netral berbasis data mencegah konflik horizontal membesar."},
{id:"TKP-311", q:"Dalam forum musyawarah warga, penyandang disabilitas tidak pernah dilibatkan. Anda ....", opts:[{t:"Mengusulkan dan memastikan mereka dilibatkan dalam forum", s:5},{t:"Mengajak mereka hadir", s:4},{t:"Menanyakan pendapat mereka terpisah", s:3},{t:"Membiarkan karena mereka tidak biasa ikut", s:2},{t:"Menganggap forum tidak cocok untuk mereka", s:1}], ex:"Inklusi berarti memberi ruang partisipasi nyata, bukan sekadar formalitas."},
{id:"TKP-312", q:"Dalam musyawarah, suara perempuan selalu diabaikan dan keputusan didominasi laki-laki. Sebagai perangkat, Anda ....", opts:[{t:"Mendorong dan memberi ruang agar suara perempuan didengar", s:5},{t:"Mengingatkan pentingnya keterwakilan", s:4},{t:"Membiarkan karena sudah budaya", s:3},{t:"Ikut mengabaikan", s:2},{t:"Melarang perempuan ikut musyawarah", s:1}], ex:"Kesetaraan gender dalam musyawarah adalah prinsip demokrasi."},
{id:"TKP-313", q:"Anak muda dan tetua adat berselisih soal cara mengelola dana kas kampung. Keduanya ngotot. Anda ....", opts:[{t:"Menjembatani dialog hingga tercapai kesepakatan yang menghormati keduanya", s:5},{t:"Mengajak musyawarah bersama", s:4},{t:"Memihak tetua adat yang lebih berpengalaman", s:3},{t:"Memihak anak muda yang lebih modern", s:2},{t:"Mengambil alih pengelolaan dana", s:1}], ex:"Menjembatani generasi mencegah perpecahan dalam masyarakat."},
{id:"TKP-314", q:"Anda menyadari tidak bisa bahasa isyarat padahal sering melayani warga tunarungu. Tindakan Anda ....", opts:[{t:"Mempelajari dasar-dasarnya secara mandiri", s:5},{t:"Mengusulkan pelatihan ke atasan", s:4},{t:"Mengandalkan tulisan saja", s:3},{t:"Membiarkan karena jarang", s:2},{t:"Menganggap bukan tanggung jawab Anda", s:1}], ex:"Inisiatif belajar demi melayani lebih baik adalah profesionalisme."},
{id:"TKP-315", q:"Warga miskin dan warga kaya antre di loket yang sama. Petugas lain cenderung mendahulukan yang kaya. Anda ....", opts:[{t:"Melayani sesuai antrean tanpa membedakan status", s:5},{t:"Menegur petugas yang pilih kasih", s:4},{t:"Mengikuti kebiasaan yang ada", s:3},{t:"Ikut mendahulukan yang kaya", s:2},{t:"Mengusir warga miskin yang protes", s:1}], ex:"Keadilan pelayanan tidak mengenal strata sosial ekonomi."},
{id:"TKP-316", q:"Korban bencana dari daerah lain mengungsi ke wilayah Anda dan butuh bantuan administrasi darurat. Anda ....", opts:[{t:"Membantu secepatnya tanpa mempersoalkan asal daerah", s:5},{t:"Membantu sesuai prosedur darurat", s:4},{t:"Mengarahkan kembali ke daerah asal", s:3},{t:"Menunda sampai ada instruksi", s:2},{t:"Menolak karena bukan warga setempat", s:1}], ex:"Kemanusiaan melampaui batas administrasi wilayah."},
{id:"TKP-317", q:"Warga memiliki kearifan lokal menjaga kebersihan sungai yang sejalan dengan program lingkungan. Sikap Anda ....", opts:[{t:"Mendukung dan mengintegrasikannya dengan program resmi", s:5},{t:"Mengapresiasi inisiatif warga", s:4},{t:"Membiarkan berjalan sendiri", s:3},{t:"Mengambil alih programnya", s:2},{t:"Mengabaikan karena tidak resmi", s:1}], ex:"Kearifan lokal adalah modal sosial yang harus didukung, bukan diabaikan."},
{id:"TKP-318", q:"Warga lintas agama ingin gotong royong memperbaiki rumah ibadah yang rusak. Mereka meminta dukungan kelurahan. Anda ....", opts:[{t:"Memfasilitasi dan mendukung penuh kegiatan tersebut", s:5},{t:"Memberi izin dan dukungan", s:4},{t:"Membiarkan tanpa terlibat", s:3},{t:"Melarang karena sensitif", s:2},{t:"Membatasi hanya untuk satu agama", s:1}], ex:"Gotong royong lintas iman adalah wujud nyata toleransi yang harus difasilitasi."},
{id:"TKP-319", q:"Pasangan beda agama mengurus administrasi pernikahan. Petugas lain menolak dengan alasan keyakinan pribadi. Anda ....", opts:[{t:"Melayani sesuai aturan yang berlaku secara profesional", s:5},{t:"Mengambil alih pengurusannya", s:4},{t:"Mengarahkan ke kantor lain", s:3},{t:"Ikut menolak", s:2},{t:"Mempersulit pengurusannya", s:1}], ex:"Keyakinan pribadi tidak boleh menghalangi kewajiban pelayanan sesuai aturan."},
{id:"TKP-320", q:"Keluarga non-muslim mengurus surat keterangan kematian. Mereka butuh prosesi sesuai keyakinannya segera. Anda ....", opts:[{t:"Memproses cepat dengan empati dan menghormati prosesi mereka", s:5},{t:"Memproses sesuai prosedur", s:4},{t:"Menunda sampai jam kerja normal", s:3},{t:"Mempersulit karena berbeda", s:2},{t:"Menolak membantu", s:1}], ex:"Duka tidak mengenal perbedaan keyakinan; empati dan kecepatan adalah kewajiban."},
{id:"TKP-321", q:"Menjelang hari besar keagamaan tertentu, banyak pegawai meminta izin bersamaan sehingga pelayanan terancam. Anda ....", opts:[{t:"Mengatur jadwal piket yang adil agar pelayanan tetap berjalan", s:5},{t:"Membagi izin secara bergiliran", s:4},{t:"Menolak semua izin", s:3},{t:"Memberi izin kepada yang meminta duluan", s:2},{t:"Menutup pelayanan", s:1}], ex:"Hak beribadah dan kewajiban pelayanan diseimbangkan dengan pengaturan adil."},
{id:"TKP-322", q:"Sebagian warga menolak program kesehatan karena dianggap bertentangan dengan adat. Program sudah berjalan. Anda ....", opts:[{t:"Berdialog dengan tokoh adat untuk mencari titik temu", s:5},{t:"Mensosialisasikan manfaat program", s:4},{t:"Memaksa program tetap jalan", s:3},{t:"Menghentikan program", s:2},{t:"Mengabaikan penolakan", s:1}], ex:"Penolakan berbasis adat diselesaikan dengan dialog, bukan pemaksaan."},
{id:"TKP-323", q:"Seni budaya lokal di wilayah Anda mulai ditinggalkan generasi muda. Sebagai perangkat daerah, Anda ....", opts:[{t:"Mempromosikan dan memfasilitasi pelestariannya", s:5},{t:"Mendukung komunitas seni yang ada", s:4},{t:"Membiarkan karena selera zaman", s:3},{t:"Menganggap tidak penting", s:2},{t:"Melarang karena kuno", s:1}], ex:"Melestarikan budaya lokal adalah bagian tugas membangun jati diri daerah."},
{id:"TKP-324", q:"Seorang warga berbicara kasar kepada Anda karena frustrasi pengurusannya lama. Anda ....", opts:[{t:"Tetap sopan, menenangkan, dan fokus menyelesaikan masalahnya", s:5},{t:"Menegur bahasanya dengan sopan", s:4},{t:"Membalas dengan ketus", s:3},{t:"Mengusirnya", s:2},{t:"Melaporkannya sebagai penghinaan", s:1}], ex:"Kesopanan petugas tidak boleh runtuh oleh kekasaran warga."},
{id:"TKP-325", q:"Seorang warga dengan gangguan jiwa datang dan berperilaku tidak biasa di ruang pelayanan. Warga lain ketakutan. Anda ....", opts:[{t:"Menanganinya dengan manusiawi dan tenang sambil menjaga kenyamanan semua", s:5},{t:"Mengajaknya bicara baik-baik", s:4},{t:"Meminta ia pergi", s:3},{t:"Mengusir dengan kasar", s:2},{t:"Menghubungi polisi untuk menangkapnya", s:1}], ex:"ODGJ adalah warga yang butuh perlakuan manusiawi, bukan ditakuti atau diusir."},
{id:"TKP-326", q:"Mantan narapidana yang sudah bebas mengurus SKCK dan dokumen lain. Petugas lain memandangnya sinis. Anda ....", opts:[{t:"Melayaninya normal tanpa stigma karena ia sudah menjalani hukuman", s:5},{t:"Melayaninya seperti warga lain", s:4},{t:"Melayaninya tetapi dengan waspada berlebih", s:3},{t:"Mempersulit pengurusannya", s:2},{t:"Menolak melayani", s:1}], ex:"Setiap warga yang telah menjalani hukuman berhak diperlakukan setara."},
{id:"TKP-327", q:"Dua warga pendukung calon berbeda bertengkar di ruang tunggu soal politik. Suasana memanas. Anda ....", opts:[{t:"Melerai dengan netral dan mengingatkan aturan ketertiban", s:5},{t:"Memisahkan keduanya", s:4},{t:"Membela yang sependapat dengan Anda", s:2},{t:"Membiarkan karena bukan urusan kantor", s:3},{t:"Ikut berdebat", s:1}], ex:"Aparat harus netral; ketertiban ruang publik didahulukan."},
{id:"TKP-328", q:"Tetua adat yang sangat dihormati datang ke musyawarah tetapi tidak diberi kesempatan bicara oleh moderator muda. Anda ....", opts:[{t:"Mengusulkan memberi kesempatan kepada beliau dengan hormat", s:5},{t:"Meminta moderator memberi giliran", s:4},{t:"Membiarkan karena sudah aturan forum", s:3},{t:"Ikut mengabaikan", s:2},{t:"Menyuruh beliau pulang saja", s:1}], ex:"Menghormati tetua adat dalam forum adalah adab bermasyarakat."},
{id:"TKP-329", q:"Seorang anak jalanan terjaring razia dan butuh pendataan serta pembinaan. Ia ketakutan. Anda ....", opts:[{t:"Menangani dengan pendekatan persuasif dan mengoordinasikan dengan dinsos", s:5},{t:"Mendata dengan baik-baik", s:4},{t:"Menyerahkan ke pihak keamanan", s:3},{t:"Membentaknya agar jera", s:2},{t:"Mengabaikannya", s:1}], ex:"Anak jalanan butuh pembinaan, bukan kekerasan; koordinasi dinsos adalah jalurnya."},
{id:"TKP-330", q:"Kantor Anda sangat beragam suku dan agama. Muncul candaan yang menyinggung SARA di grup kerja. Anda ....", opts:[{t:"Mengingatkan bahwa candaan SARA tidak pantas dan mengajak saling menghormati", s:5},{t:"Menegur pembuatnya secara pribadi", s:4},{t:"Diam karena hanya bercanda", s:3},{t:"Ikut tertawa", s:2},{t:"Membalas dengan candaan SARA lain", s:1}], ex:"Keberagaman di tempat kerja dijaga dengan tidak menoleransi candaan SARA."},
{id:"TKP-331", q:"Anda menerima laporan data kependudukan warga bocor dan tersebar di grup WhatsApp. Sebagai petugas, Anda ....", opts:[{t:"Melaporkan ke atasan dan membantu pengamanan serta mitigasi segera", s:5},{t:"Melaporkan kepada atasan", s:4},{t:"Menghapus pesan yang Anda terima", s:3},{t:"Menyebarkan agar warga waspada", s:2},{t:"Mengabaikan karena bukan Anda yang membocorkan", s:1}], ex:"Kebocoran data ditangani cepat lewat jalur resmi, bukan disebarluaskan."},
{id:"TKP-332", q:"Beredar pesan berantai mengatasnamakan dinas Anda meminta warga mentransfer biaya administrasi. Warga bertanya kebenarannya. Anda ....", opts:[{t:"Menegaskan itu penipuan, mengedukasi warga, dan melaporkannya", s:5},{t:"Mengumumkan bahwa itu bukan dari dinas", s:4},{t:"Menjawab yang bertanya saja", s:3},{t:"Membiarkan karena warga harusnya paham", s:2},{t:"Ikut meneruskan pesan tersebut", s:1}], ex:"Penipuan mengatasnamakan instansi dilawan dengan edukasi dan klarifikasi resmi."},
{id:"TKP-333", q:"Rekan meminta password akun sistem pelayanan Anda karena ia lupa miliknya dan ada warga menunggu. Anda ....", opts:[{t:"Menolak dan membantunya mengurus reset password resmi", s:5},{t:"Menolak dengan halus", s:4},{t:"Memberi sementara lalu mengganti", s:3},{t:"Memberikan karena ia rekan dekat", s:2},{t:"Memberikan dan mencatatnya bersama", s:1}], ex:"Kredensial akun tidak boleh dibagi dalam kondisi apa pun; ada prosedur reset resmi."},
{id:"TKP-334", q:"Sistem input data down tepat saat Anda menginput berkas warga yang antre. Tindakan Anda ....", opts:[{t:"Mencatat manual dengan rapi lalu menginput ulang saat sistem pulih", s:5},{t:"Mencatat manual seadanya", s:4},{t:"Meminta warga kembali besok", s:3},{t:"Menutup loket", s:2},{t:"Mengarang data agar terlihat selesai", s:1}], ex:"Pencatatan manual yang rapi memastikan tidak ada data hilang saat gangguan."},
{id:"TKP-335", q:"Beredar hoaks bahwa layanan KTP ditiadakan dan diganti berbayar. Banyak warga panik bertanya. Anda ....", opts:[{t:"Membuat klarifikasi resmi dan menyebarkannya di kanal yang sama dengan hoaksnya", s:5},{t:"Menjelaskan kepada warga yang bertanya", s:4},{t:"Melaporkan penyebar hoaks", s:3},{t:"Membiarkan karena akan reda sendiri", s:2},{t:"Ikut menyebarkan agar heboh", s:1}], ex:"Hoaks dilawan di tempat ia menyebar dengan informasi resmi yang mudah dipahami."},
{id:"TKP-336", q:"Foto dokumen pribadi warga yang diurus di loket Anda tersebar di media sosial. Diduga dari lingkungan kantor. Anda ....", opts:[{t:"Melaporkan segera dan membantu investigasi serta pencegahan", s:5},{t:"Melaporkan kepada atasan", s:4},{t:"Menghapus foto yang Anda lihat", s:3},{t:"Menyalahkan warga yang memfoto", s:2},{t:"Menyembunyikan karena takut disalahkan", s:1}], ex:"Pelanggaran privasi warga adalah masalah serius yang wajib dilaporkan."},
{id:"TKP-337", q:"Aplikasi pelayanan baru gagal diperbarui dan tidak bisa dibuka saat jam sibuk. Warga sudah antre. Anda ....", opts:[{t:"Menghubungi helpdesk sambil melayani manual sementara", s:5},{t:"Melayani manual tanpa melapor", s:4},{t:"Menutup layanan sampai aplikasi normal", s:3},{t:"Menyalahkan pengembang aplikasi", s:2},{t:"Pulang karena tidak bisa kerja", s:1}], ex:"Gangguan aplikasi diatasi paralel: lapor teknis dan tetap melayani manual."},
{id:"TKP-338", q:"Seorang lansia kebingungan menggunakan aplikasi pendaftaran online yang kini wajib. Ia sudah mencoba berkali-kali. Anda ....", opts:[{t:"Memandunya dengan sabar sampai bisa, atau membantu mendaftarkan", s:5},{t:"Membantu mendaftarkannya", s:4},{t:"Menyuruh cucunya yang membantu", s:3},{t:"Menyuruhnya belajar sendiri", s:2},{t:"Menolak karena pendaftaran harus mandiri", s:1}], ex:"Transformasi digital tidak boleh meninggalkan warga yang gaptek."},
{id:"TKP-339", q:"Atasan meminta Anda rutin mem-backup data pelayanan, tetapi Anda sibuk. Sikap Anda ....", opts:[{t:"Menjadwalkannya rutin karena data adalah aset penting", s:5},{t:"Melakukannya bila sempat", s:4},{t:"Meminta rekan yang mengerjakan", s:3},{t:"Mengabaikan karena belum pernah hilang", s:2},{t:"Menolak karena bukan tugas Anda", s:1}], ex:"Backup rutin adalah disiplin kecil yang mencegah bencana besar."},
{id:"TKP-340", q:"Anda tergoda memakai email dinas untuk mendaftar layanan pribadi agar terlihat resmi. Tindakan Anda ....", opts:[{t:"Tidak melakukannya; email dinas hanya untuk urusan dinas", s:5},{t:"Mengurungkan niat", s:4},{t:"Memakai sekali saja", s:3},{t:"Memakai karena tidak ada yang tahu", s:2},{t:"Memakai dan menyalahgunakannya", s:1}], ex:"Fasilitas dinas, termasuk email, hanya untuk kepentingan dinas."},
{id:"TKP-341", q:"Kantor mulai memakai tanda tangan digital. Anda belum paham cara pakainya dan ada surat mendesak. Anda ....", opts:[{t:"Mempelajari cepat dari panduan atau bertanya agar surat tetap resmi", s:5},{t:"Meminta bantuan rekan yang bisa", s:4},{t:"Memakai tanda tangan basah saja", s:3},{t:"Menunda suratnya", s:2},{t:"Memalsukan tanda tangan digital atasan", s:1}], ex:"Adaptasi teknologi adalah kewajiban; ketidaktahuan diatasi dengan belajar."},
{id:"TKP-342", q:"Rapat koordinasi online terganggu koneksi Anda tepat saat giliran presentasi. Anda ....", opts:[{t:"Segera mencari solusi: hotspot, pindah ruangan, atau melanjutkan via telepon", s:5},{t:"Mencoba menyambung kembali", s:4},{t:"Meminta giliran di akhir", s:3},{t:"Keluar dari rapat", s:2},{t:"Menyalahkan penyedia internet", s:1}], ex:"Kendala teknis diatasi proaktif agar tidak menghambat forum."},
{id:"TKP-343", q:"Website resmi dinas diretas dan menampilkan konten tidak pantas. Anda mengetahuinya pertama kali. Tindakan Anda ....", opts:[{t:"Segera melaporkan ke tim IT dan atasan untuk penanganan cepat", s:5},{t:"Melaporkan kepada atasan", s:4},{t:"Mengambil tangkapan layar lalu diam", s:3},{t:"Menyebarkan kabar peretasan", s:2},{t:"Mengabaikan karena bukan bidang Anda", s:1}], ex:"Insiden siber dilaporkan secepatnya; kecepatan respons meminimalkan kerusakan."},
{id:"TKP-344", q:"Ditemukan data ganda dengan NIK sama tetapi nama berbeda di sistem. Warga yang bersangkutan kebingungan. Anda ....", opts:[{t:"Memverifikasi ke dukcapil dan membantu perbaikan datanya", s:5},{t:"Melaporkan ke dukcapil", s:4},{t:"Memilih salah satu data", s:3},{t:"Membiarkan karena kesalahan sistem", s:2},{t:"Menuduh warga memalsukan data", s:1}], ex:"Anomali data diselesaikan lewat verifikasi resmi, bukan tebakan."},
{id:"TKP-345", q:"Seorang warga menunjukkan QR code bukti pendaftaran yang terlihat mencurigakan. Anda ....", opts:[{t:"Memverifikasi keasliannya di sistem sebelum memproses", s:5},{t:"Memeriksa manual kecocokannya", s:4},{t:"Menerima apa adanya", s:3},{t:"Menolak langsung", s:2},{t:"Menuduhnya penipu", s:1}], ex:"Verifikasi sebelum menuduh; kehati-hatian melindungi tanpa memfitnah."},
{id:"TKP-346", q:"Banyak lansia di wilayah Anda kesulitan mengakses layanan digital. Sebagai perangkat, Anda ....", opts:[{t:"Mengusulkan dan membantu edukasi literasi digital bagi mereka", s:5},{t:"Membantu yang datang satu per satu", s:4},{t:"Menganggap itu tugas dinas kominfo", s:3},{t:"Membiarkan karena zaman berubah", s:2},{t:"Menyuruh mereka beradaptasi sendiri", s:1}], ex:"Inisiatif edukasi digital menunjukkan keberpihakan pada warga rentan."},
{id:"TKP-347", q:"Arsip fisik menumpuk sementara arsip digital belum tertata. Atasan meminta perbaikan. Anda ....", opts:[{t:"Menyusun sistem pengelolaan keduanya secara bertahap dan konsisten", s:5},{t:"Mulai menata yang paling penting", s:4},{t:"Fokus digital saja", s:3},{t:"Membuang arsip lama", s:2},{t:"Mengabaikan karena merepotkan", s:1}], ex:"Penataan arsip bertahap dan konsisten lebih baik daripada janji besar tanpa aksi."},
{id:"TKP-348", q:"CCTV ruang pelayanan mati dan tidak ada yang melaporkan. Anda menyadarinya. Tindakan Anda ....", opts:[{t:"Melaporkan agar segera diperbaiki demi keamanan dan transparansi", s:5},{t:"Memberitahu bagian umum", s:4},{t:"Membiarkan karena bukan tugas Anda", s:3},{t:"Senang karena tidak diawasi", s:2},{t:"Merusaknya lebih lanjut", s:1}], ex:"Sarana pengawasan mendukung integritas; kerusakannya wajib dilaporkan."},
{id:"TKP-349", q:"Kantor menerapkan aplikasi baru yang mengubah seluruh alur kerja Anda. Rekan-rekan mengeluh. Sikap Anda ....", opts:[{t:"Mempelajarinya sungguh-sungguh dan membantu rekan beradaptasi", s:5},{t:"Mempelajari dan menjalankannya", s:4},{t:"Mengeluh bersama rekan", s:3},{t:"Menolak menggunakannya", s:2},{t:"Menghasut rekan menolak", s:1}], ex:"Perubahan teknologi dihadapi dengan belajar dan saling membantu, bukan resistensi."},
{id:"TKP-350", q:"Seorang ASN memposting keluhan bernada SARA tentang warga di akun pribadinya yang viral. Anda rekannya. Sikap Anda ....", opts:[{t:"Mengingatkannya bahwa itu melanggar etika ASN dan berisiko sanksi", s:5},{t:"Menasihatinya menghapus postingan", s:4},{t:"Diam karena akun pribadi", s:3},{t:"Ikut berkomentar mendukung", s:2},{t:"Ikut menyebarkan", s:1}], ex:"ASN terikat etika bermedia sosial; mengingatkan rekan adalah kepedulian."},
{id:"TKP-351", q:"Seorang penceramah di masjid kantor menyampaikan materi yang mengkafirkan pemerintah yang sah. Anda pengurus masjid. Tindakan Anda ....", opts:[{t:"Menegur dan menghentikan materi provokatif serta memastikan penceramah berikutnya sesuai ketentuan", s:5},{t:"Melaporkan kepada atasan", s:4},{t:"Membiarkan karena kebebasan berpendapat", s:3},{t:"Ikut menyetujui", s:2},{t:"Menyebarkan ceramahnya", s:1}], ex:"Fasilitas negara tidak boleh menjadi mimbar provokasi anti pemerintah."},
{id:"TKP-352", q:"Rekan kerja menyebarkan konten intoleran di grup WhatsApp kantor. Beberapa anggota mulai terpengaruh. Anda ....", opts:[{t:"Menegur dan mengingatkan bahaya intoleransi, serta melaporkan bila berlanjut", s:5},{t:"Menegurnya secara pribadi", s:4},{t:"Keluar dari grup", s:3},{t:"Diam karena takut dimusuhi", s:2},{t:"Ikut menyebarkan", s:1}], ex:"Intoleransi di lingkungan kerja harus dilawan sejak dini."},
{id:"TKP-353", q:"Warga melaporkan tetangganya yang diduga terpapar paham radikal dan sering menghasut. Anda ....", opts:[{t:"Mengoordinasikan dengan aparat dan tokoh masyarakat untuk pembinaan", s:5},{t:"Melaporkan kepada aparat berwenang", s:4},{t:"Menasihati warga pelapor agar tidak ikut terpengaruh", s:3},{t:"Mengabaikan laporan", s:2},{t:"Ikut menghasut balik", s:1}], ex:"Dugaan radikalisme ditangani aparat dengan pendekatan pembinaan."},
{id:"TKP-354", q:"Di grup warga, ada ajakan mengikuti aksi yang berpotensi anarkis mengatasnamakan agama. Anda anggota grup. Sikap Anda ....", opts:[{t:"Menolak ajakan dan mengingatkan bahayanya, serta melaporkan bila perlu", s:5},{t:"Tidak ikut dan keluar dari pembahasan", s:4},{t:"Diam mengamati", s:3},{t:"Ikut karena penasaran", s:2},{t:"Ikut menyebarkan ajakan", s:1}], ex:"Menolak ajakan anarkis dan mengingatkan adalah tanggung jawab warga negara."},
{id:"TKP-355", q:"Ditemukan simbol organisasi terlarang terpampang di fasilitas umum wilayah Anda. Tindakan Anda ....", opts:[{t:"Menertibkan segera dan melaporkan kepada aparat", s:5},{t:"Melaporkan kepada atasan", s:4},{t:"Menghapus sendiri diam-diam", s:3},{t:"Membiarkan karena takut", s:2},{t:"Ikut memasang", s:1}], ex:"Simbol terlarang tidak boleh dibiarkan terpampang di ruang publik."},
{id:"TKP-356", q:"Di lingkungan Anda berkembang paham yang menolak Pancasila. Beberapa pemuda mulai terpengaruh. Sebagai perangkat, Anda ....", opts:[{t:"Aktif membina wawasan kebangsaan melalui dialog dan kegiatan positif", s:5},{t:"Melaporkan kepada aparat", s:4},{t:"Mengajak dialog", s:3},{t:"Membiarkan karena hak berpendapat", s:2},{t:"Ikut terpengaruh", s:1}], ex:"Pembinaan wawasan kebangsaan adalah benteng melawan paham anti Pancasila."},
{id:"TKP-357", q:"Seorang remaja di wilayah Anda terlihat mulai terpapar konten ekstrem di media sosialnya. Orang tuanya meminta bantuan Anda. Tindakan Anda ....", opts:[{t:"Merangkul dan mengedukasi remaja tersebut dengan pendekatan persuasif", s:5},{t:"Berdialog dengan remaja dan orang tuanya", s:4},{t:"Melaporkan ke aparat", s:3},{t:"Menghakimi remaja tersebut", s:2},{t:"Mengabaikan", s:1}], ex:"Remaja terpapar dirangkul dan diedukasi, bukan dihakimi."},
{id:"TKP-358", q:"Ada aliran dana mencurigakan untuk kegiatan keagamaan di wilayah Anda yang tidak jelas sumbernya. Anda ....", opts:[{t:"Melaporkan kepada aparat berwenang untuk ditelusuri", s:5},{t:"Menyelidiki awal secara hati-hati", s:4},{t:"Menanyakan ke panitia", s:3},{t:"Membiarkan karena urusan agama", s:2},{t:"Ikut menerima dananya", s:1}], ex:"Dana mencurigakan berpotensi terkait pendanaan ekstremisme; wajib dilaporkan."},
{id:"TKP-359", q:"Di media sosial beredar ujaran kebencian bernuansa SARA yang memecah belah warga wilayah Anda. Sebagai ASN, Anda ....", opts:[{t:"Melawannya dengan narasi damai dan melaporkan kontennya", s:5},{t:"Membuat konten penyeimbang yang menyejukkan", s:4},{t:"Tidak ikut campur", s:3},{t:"Ikut berkomentar memanas", s:2},{t:"Ikut menyebarkan", s:1}], ex:"ASN menjadi penyejuk di ruang digital dengan narasi damai."},
{id:"TKP-360", q:"Sebagai ASN, Anda diminta menjadi teladan komitmen kebangsaan di tengah maraknya paham yang mengancam persatuan. Wujud nyata Anda ....", opts:[{t:"Mengamalkan nilai Pancasila dalam kerja dan kehidupan sehari-hari secara konsisten", s:5},{t:"Mengikuti upacara dan kegiatan kebangsaan", s:4},{t:"Memasang simbol negara di ruangan", s:3},{t:"Berkomitmen dalam hati saja", s:2},{t:"Menganggapnya formalitas", s:1}], ex:"Komitmen kebangsaan dibuktikan dengan pengamalan nyata, bukan simbol semata."},
];
